window.__EC_DOC_option_matrix = {"id":{"desc":"<p>Component ID, not specified by default. If specified, it can be used to refer the component in option or API.</p>\n"},"zlevel":{"desc":"<p><code class=\"codespan\">zlevel</code> value of all graphical elements in .</p>\n<p><code class=\"codespan\">zlevel</code> is used to make layers with Canvas. Graphical elements with different <code class=\"codespan\">zlevel</code> values will be placed in different Canvases, which is a common optimization technique. We can put those frequently changed elements (like those with animations) to a separate <code class=\"codespan\">zlevel</code>. Notice that too many Canvases will increase memory cost, and should be used carefully on mobile phones to avoid crash.</p>\n<p>Canvases with bigger <code class=\"codespan\">zlevel</code> will be placed on Canvases with smaller <code class=\"codespan\">zlevel</code>.</p>\n"},"z":{"desc":"<p><code class=\"codespan\">z</code> value of all graphical elements in , which controls order of drawing graphical components. Components with smaller <code class=\"codespan\">z</code> values may be overwritten by those with larger <code class=\"codespan\">z</code> values.</p>\n<p><code class=\"codespan\">z</code> has a lower priority to <code class=\"codespan\">zlevel</code>, and will not create new Canvas.</p>\n"},"left":{"desc":"<p>Distance between undefined component and the left side of the container.</p>\n<p><code class=\"codespan\">left</code> can be a pixel value like <code class=\"codespan\">20</code>; it can also be a percentage value relative to container width like <code class=\"codespan\">&#39;20%&#39;</code>; and it can also be <code class=\"codespan\">&#39;left&#39;</code>, <code class=\"codespan\">&#39;center&#39;</code>, or <code class=\"codespan\">&#39;right&#39;</code>.</p>\n<p>If the <code class=\"codespan\">left</code> value is set to be <code class=\"codespan\">&#39;left&#39;</code>, <code class=\"codespan\">&#39;center&#39;</code>, or <code class=\"codespan\">&#39;right&#39;</code>, then the component will be aligned automatically based on position.</p>\n","uiControl":{"type":"percent","default":"0%"}},"top":{"desc":"<p>Distance between undefined component and the top side of the container.</p>\n<p><code class=\"codespan\">top</code> can be a pixel value like <code class=\"codespan\">20</code>; it can also be a percentage value relative to container width like <code class=\"codespan\">&#39;20%&#39;</code>; and it can also be <code class=\"codespan\">&#39;top&#39;</code>, <code class=\"codespan\">&#39;middle&#39;</code>, or <code class=\"codespan\">&#39;bottom&#39;</code>.</p>\n<p>If the <code class=\"codespan\">top</code> value is set to be <code class=\"codespan\">&#39;top&#39;</code>, <code class=\"codespan\">&#39;middle&#39;</code>, or <code class=\"codespan\">&#39;bottom&#39;</code>, then the component will be aligned automatically based on position.</p>\n","uiControl":{"type":"percent","default":"0%"}},"right":{"desc":"<p>Distance between undefined component and the right side of the container.</p>\n<p><code class=\"codespan\">right</code> can be a pixel value like <code class=\"codespan\">20</code>; it can also be a percentage value relative to container width like <code class=\"codespan\">&#39;20%&#39;</code>.</p>\n<p>Adaptive by default.</p>\n","uiControl":{"type":"percent","default":"0%"}},"bottom":{"desc":"<p>Distance between undefined component and the bottom side of the container.</p>\n<p><code class=\"codespan\">bottom</code> can be a pixel value like <code class=\"codespan\">20</code>; it can also be a percentage value relative to container width like <code class=\"codespan\">&#39;20%&#39;</code>.</p>\n<p>Adaptive by default.</p>\n","uiControl":{"type":"percent","default":"0%"}},"width":{"desc":"<p>Width of matrix component. Adaptive by default.</p>\n","uiControl":{"type":"percent","default":"50%"}},"height":{"desc":"<p>Height of matrix component. Adaptive by default.</p>\n","uiControl":{"type":"percent","default":"50%"}},"x":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>X-axis header region.</p>\n"},"x.show":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Determines whether to display the header row(in <code class=\"codespan\">matrix.x</code>)/column(in <code class=\"codespan\">matrix.y</code>).</p>\n"},"x.data":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Specifies the data for the x-axis cells. i.e., defined the column/row.</p>\n<pre><code class=\"lang-js\">// Data for a single row\ndata: [&#39;A&#39;, &#39;B&#39;, &#39;C&#39;, &#39;D&#39;, &#39;E&#39;]\n\n// Or if column/row names is not of concern, simply\ndata: Array(5).fill(null) // Five columns or rows\n\n// Data in a tree structure\ndata: [{\n    value: &#39;A&#39;,\n    children: [\n        {\n            value: &#39;A1&#39;,\n            children: [\n                {value: &#39;A1-1&#39;},\n                {value: &#39;A1-2&#39;}\n            ]\n        },\n        {value: &#39;A2&#39;}\n    ]\n}, {\n    value: &#39;B&#39;,\n    children: [\n        {value: &#39;B1&#39;},\n        {value: &#39;B2&#39;}\n    ]\n}]\n</code></pre>\n"},"x.data.value":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>The text in the header cell. Can also be used as a index of this column or row. Optional. If not specified, auto generate a text.</p>\n"},"x.data.children":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>See <a href=\"#matrix.x.data\">matrix.x/y.data</a>.</p>\n"},"x.data.size":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p><strong>[[The rule of cell size]]</strong></p>\n<ul>\n<li>option <code class=\"codespan\">levelSize</code><ul>\n<li>It specifies the size of all cells in a row or a column.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell height of a row (&quot;level&quot; refers to a row).</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell width of a column (&quot;level&quot; refers to a column).</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.levelSize</code> specifies the default size of every columns or rows.</li>\n<li><code class=\"codespan\">matrix.levels[i].levelSize</code> specifies the size of a certain column or row.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>option <code class=\"codespan\">size</code><ul>\n<li>It specifies the size of a single cell.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell width.</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell height.</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.x/y.data[i].size</code></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p>The value of <code class=\"codespan\">levelSize</code> or <code class=\"codespan\">size</code> can be:</p>\n<ul>\n<li>Unspecified(default): The width or height is evenly distributed.</li>\n<li><code class=\"codespan\">number</code>: Represents pixel value.</li>\n<li><code class=\"codespan\">string</code>: Percentage value (e.g., <code class=\"codespan\">&#39;33%&#39;</code>), representing the percentage relative to the width (in <code class=\"codespan\">matrix.x</code>) or height (in <code class=\"codespan\">matrix.y</code>) of the matrix.</li>\n</ul>\n<p>For example:</p>\n<pre><code class=\"lang-js\">{\n    matrix: {\n        x: {\n            // The height of the second row is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other row height are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The width of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell width are evenly distributed.\n                // ...\n            ]\n        },\n        y: {\n            // The width of the second column is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other column width are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The height of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell height are evenly distributed.\n                // ...\n            ]\n        },\n        // ...\n    },\n}\n</code></pre>\n"},"x.label":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Text label of x-axis cells, to explain some data information about graphic item like value, name and so on. <code class=\"codespan\">label</code> is placed under <code class=\"codespan\">itemStyle</code> in ECharts 2.x. In ECharts 3, to make the configuration structure flatter, <code class=\"codespan\">label</code>is taken to be at the same level with <code class=\"codespan\">itemStyle</code>, and has <code class=\"codespan\">emphasis</code> as <code class=\"codespan\">itemStyle</code> does.</p>\n"},"x.label.show":{"desc":"\n\n<p>Whether to show label.</p>\n","uiControl":{"type":"boolean","default":"false"}},"x.label.position":{"desc":"\n\n\n\n<p>Label position.</p>\n<p><strong>Followings are the options: </strong></p>\n<ul>\n<li><p>[x, y]</p>\n<p>  Use relative percentage, or absolute pixel values to represent position of label relative to top-left corner of bounding box.\n  For example:</p>\n<pre><code class=\"lang-ts\">  // Absolute pixel values\n  position: [10, 10],\n  // Relative percentage\n  position: [&#39;50%&#39;, &#39;50%&#39;]\n</code></pre>\n</li>\n<li><p>&#39;top&#39;</p>\n</li>\n<li>&#39;left&#39;</li>\n<li>&#39;right&#39;</li>\n<li>&#39;bottom&#39;</li>\n<li>&#39;inside&#39;</li>\n<li>&#39;insideLeft&#39;</li>\n<li>&#39;insideRight&#39;</li>\n<li>&#39;insideTop&#39;</li>\n<li>&#39;insideBottom&#39;</li>\n<li>&#39;insideTopLeft&#39;</li>\n<li>&#39;insideBottomLeft&#39;</li>\n<li>&#39;insideTopRight&#39;</li>\n<li>&#39;insideBottomRight&#39;</li>\n</ul>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/view.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"enum","options":"top,left,right,bottom,inside,insideLeft,insideRight,insideTop,insideBottom,insideTopLeft,insideBottomLeft,insideTopRight,insideBottomRight,outside"}},"x.label.distance":{"desc":"\n\n<p>Distance to the host graphic element.</p>\n<p>It is valid only when <code class=\"codespan\">position</code> is string value (like <code class=\"codespan\">&#39;top&#39;</code>、<code class=\"codespan\">&#39;insideRight&#39;</code>).</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"number","default":"5","min":"0","step":"0.5"}},"x.label.rotate":{"desc":"\n\n<p>Rotate label, from -90 degree to 90, positive value represents rotate anti-clockwise.</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=bar-label-rotation\" target=\"_blank\">label rotation</a>.</p>\n","uiControl":{"type":"angle","default":"0","min":"-90","max":"90","step":"1"}},"x.label.offset":{"desc":"\n\n<p>Whether to move text slightly. For example: <code class=\"codespan\">[30, 40]</code> means move <code class=\"codespan\">30</code> horizontally and move <code class=\"codespan\">40</code> vertically.</p>\n","uiControl":{"type":"vector","dims":"x,y","step":"0.5","separate":"true"}},"x.label.formatter":{"desc":"<p>Data label formatter, which supports string template and callback function. In either form, <code class=\"codespan\">\\n</code> is supported to represent a new line.</p>\n<p><strong>String template</strong></p>\n<p>Model variation includes:</p>\n<ul>\n<li><code class=\"codespan\">{a}</code>: series name.</li>\n<li><code class=\"codespan\">{b}</code>: the name of a data item.</li>\n<li><code class=\"codespan\">{c}</code>: the value of a data item.</li>\n<li><code class=\"codespan\">{@xxx}</code>: the value of a dimension named <code class=\"codespan\">&#39;xxx&#39;</code>, for example, <code class=\"codespan\">{@product}</code> refers the value of <code class=\"codespan\">&#39;product&#39;</code> dimension.</li>\n<li><code class=\"codespan\">{@[n]}</code>: the value of a dimension at the index of <code class=\"codespan\">n</code>, for example, <code class=\"codespan\">{@[3]}</code> refers the value at dimensions[3].</li>\n</ul>\n<p><strong>example: </strong></p>\n<pre><code class=\"lang-ts\">formatter: &#39;{b}: {@score}&#39;\n</code></pre>\n<p><strong>Callback function</strong></p>\n<p>Callback function is in form of:</p>\n<pre><code class=\"lang-ts\">(params: Object|Array) =&gt; string\n</code></pre>\n<p>where <code class=\"codespan\">params</code> is the single dataset needed by formatter, which is formed as:</p>\n<pre><code class=\"lang-ts\">{\n    componentType: &#39;series&#39;,\n    // Series type\n    seriesType: string,\n    // Series index in option.series\n    seriesIndex: number,\n    // Series name\n    seriesName: string,\n    // Data name, or category name\n    name: string,\n    // Data index in input data array\n    dataIndex: number,\n    // Original data as input\n    data: Object,\n    // Value of data. In most series it is the same as data.\n    // But in some series it is some part of the data (e.g., in map, radar)\n    value: number|Array|Object,\n    // encoding info of coordinate system\n    // Key: coord, like (&#39;x&#39; &#39;y&#39; &#39;radius&#39; &#39;angle&#39;)\n    // value: Must be an array, not null/undefined. Contain dimension indices, like:\n    // {\n    //     x: [2] // values on dimension index 2 are mapped to x axis.\n    //     y: [0] // values on dimension index 0 are mapped to y axis.\n    // }\n    encode: Object,\n    // dimension names list\n    dimensionNames: Array&lt;String&gt;,\n    // data dimension index, for example 0 or 1 or 2 ...\n    // Only work in `radar` series.\n    dimensionIndex: number,\n    // Color of data\n    color: string\n}\n</code></pre>\n<p><strong>How to use <code class=\"codespan\">encode</code> and <code class=\"codespan\">dimensionNames</code>?</strong></p>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    source: [\n        [&#39;Matcha Latte&#39;, 43.3, 85.8, 93.7],\n        [&#39;Milk Tea&#39;, 83.1, 73.4, 55.1],\n        [&#39;Cheese Cocoa&#39;, 86.4, 65.2, 82.5],\n        [&#39;Walnut Brownie&#39;, 72.4, 53.9, 39.1]\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.encode.y[0]]\n</code></pre>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    dimensions: [&#39;product&#39;, &#39;2015&#39;, &#39;2016&#39;, &#39;2017&#39;],\n    source: [\n        {product: &#39;Matcha Latte&#39;, &#39;2015&#39;: 43.3, &#39;2016&#39;: 85.8, &#39;2017&#39;: 93.7},\n        {product: &#39;Milk Tea&#39;, &#39;2015&#39;: 83.1, &#39;2016&#39;: 73.4, &#39;2017&#39;: 55.1},\n        {product: &#39;Cheese Cocoa&#39;, &#39;2015&#39;: 86.4, &#39;2016&#39;: 65.2, &#39;2017&#39;: 82.5},\n        {product: &#39;Walnut Brownie&#39;, &#39;2015&#39;: 72.4, &#39;2016&#39;: 53.9, &#39;2017&#39;: 39.1}\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.dimensionNames[params.encode.y[0]]]\n</code></pre>\n"},"x.label.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#333"}},"x.label.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"x.label.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"x.label.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"x.label.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"x.label.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"x.label.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"x.label.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"x.label.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"x.label.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"x.label.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"x.label.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"x.label.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"x.label.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"x.label.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"x.label.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.width":{"desc":"\n\n<p>Width of text block.</p>\n","uiControl":{"type":"number","default":"100","min":"1","max":"500","step":"1"}},"x.label.height":{"desc":"\n\n<p>Height of text block.</p>\n","uiControl":{"type":"number","default":"50","min":"1","max":"500","step":"1"}},"x.label.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"x.label.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"x.label.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"x.label.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"x.label.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.overflow":{"desc":"\n\n<p>Determine how to display the text when it&#39;s overflow. Available when <code class=\"codespan\">width</code> is set.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the text and trailing with <code class=\"codespan\">ellipsis</code>.</li>\n<li><code class=\"codespan\">&#39;break&#39;</code> Break by word</li>\n<li><code class=\"codespan\">&#39;breakAll&#39;</code> Break by character.</li>\n</ul>\n","uiControl":{"type":"enum","options":"truncate,break,breakAll"}},"x.label.ellipsis":{"desc":"<p>Ellipsis to be displayed when <code class=\"codespan\">overflow</code> is set to <code class=\"codespan\">truncate</code>.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the overflow lines.</li>\n</ul>\n"},"x.label.rich":{"desc":"<p>&quot;Rich text styles&quot; can be defined in this <code class=\"codespan\">rich</code> property. For example:</p>\n<pre><code class=\"lang-ts\">label: {\n    // Styles defined in &#39;rich&#39; can be applied to some fragments\n    // of text by adding some markers to those fragment, like\n    // `{styleName|text content text content}`.\n    // `&#39;\\n&#39;` is the newline character.\n    formatter: [\n        &#39;{a|Style &quot;a&quot; is applied to this snippet}&#39;\n        &#39;{b|Style &quot;b&quot; is applied to this snippet}This snippet use default style{x|use style &quot;x&quot;}&#39;\n    ].join(&#39;\\n&#39;),\n\n    rich: {\n        a: {\n            color: &#39;red&#39;,\n            lineHeight: 10\n        },\n        b: {\n            backgroundColor: {\n                image: &#39;xxx/xxx.jpg&#39;\n            },\n            height: 40\n        },\n        x: {\n            fontSize: 18,\n            fontFamily: &#39;Microsoft YaHei&#39;,\n            borderColor: &#39;#449933&#39;,\n            borderRadius: 4\n        },\n        ...\n    }\n}\n</code></pre>\n<p>For more details, see <a href=\"tutorial.html#Rich%20Text\" target=\"_blank\">Rich Text</a> please.</p>\n"},"x.label.rich.<style_name>.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"null"}},"x.label.rich.<style_name>.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"x.label.rich.<style_name>.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"x.label.rich.<style_name>.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"x.label.rich.<style_name>.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"x.label.rich.<style_name>.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"x.label.rich.<style_name>.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"x.label.rich.<style_name>.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"x.label.rich.<style_name>.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"x.label.rich.<style_name>.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"x.label.rich.<style_name>.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.rich.<style_name>.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"x.label.rich.<style_name>.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"x.label.rich.<style_name>.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"x.label.rich.<style_name>.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"x.label.rich.<style_name>.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"x.label.rich.<style_name>.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.rich.<style_name>.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.rich.<style_name>.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.rich.<style_name>.width":{"desc":"<p>Width of the text block. It is the width of the text by default. In most cases, there is no need to specify it. You may want to use it in some cases like make simple table or using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p><code class=\"codespan\">width</code> can also be percent string, like <code class=\"codespan\">&#39;100%&#39;</code>, which represents the percent of <code class=\"codespan\">contentWidth</code> (that is, the width without <code class=\"codespan\">padding</code>) of its container box. It is based on <code class=\"codespan\">contentWidth</code> because that each text fragment is layout based on the <code class=\"codespan\">content box</code>, where it makes no sense that calculating width based on <code class=\"codespan\">outerWith</code> in prectice.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"x.label.rich.<style_name>.height":{"desc":"<p>Height of the text block. It is the width of the text by default. You may want to use it in some cases like using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"x.label.rich.<style_name>.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"x.label.rich.<style_name>.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.rich.<style_name>.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"x.label.rich.<style_name>.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"x.label.rich.<style_name>.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"x.label.rich.<style_name>.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"x.label.rich.<style_name>.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.rich.<style_name>.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"x.label.richInheritPlainLabel":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Whether rich text inherits plain text style.</p>\n<p>This option is just for backward compatibility.</p>\n<blockquote>\n<p>The <a href=\"#series-scatter.label.rich\">label.rich / textStyle.rich</a> <code class=\"codespan\">fontStyle</code>, <code class=\"codespan\">fontWeight</code>, <code class=\"codespan\">fontSize</code>, <code class=\"codespan\">fontFamily</code>, <code class=\"codespan\">textShadowColor</code>, <code class=\"codespan\">textShadowBlur</code>, <code class=\"codespan\">textShadowOffsetX</code>, <code class=\"codespan\">textShadowOffsetY</code> are changed to inherit the corresponding <a href=\"#series-scatter.label\">plain label styles</a> since echarts v6. You can use <code class=\"codespan\">richInheritPlainLabel: false</code> to restore it. For example,</p>\n<pre><code class=\"lang-js\">option = {\n    richInheritPlainLabel: false, // In most cases, this is enough.\n    xxx1: {\n        // Can also set it here to only control this label.\n        label: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    },\n    xxx2: {\n        textStyle: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    }\n}\n</code></pre>\n</blockquote>\n"},"x.itemStyle":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Graphic style of x-axis cells, <code class=\"codespan\">emphasis</code> is the style when it is highlighted, like being hovered by mouse, or highlighted via legend connect.</p>\n"},"x.itemStyle.color":{"desc":"\n\n<p>x-axis cells color. </p>\n<blockquote>\n<p>Supports setting as solid color using <code class=\"codespan\">rgb(255,255,255)</code>, <code class=\"codespan\">rgba(255,255,255,1)</code>, <code class=\"codespan\">#fff</code>, etc. Also supports setting as gradient color and pattern fill, see <a href=\"#color\">option.color</a> for details</p>\n</blockquote>\n","uiControl":{"type":"color"}},"x.itemStyle.borderColor":{"desc":"\n\n<p>x-axis cells border color, whose format is similar to that of <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color"}},"x.itemStyle.borderWidth":{"desc":"\n\n<p>x-axis cells border width. No border when it is set to be 0.</p>\n<p>x-axis cells border width. No border when it is set to be 0.</p>\n","uiControl":{"type":"number","value":"1","min":"0","step":"0.5"}},"x.itemStyle.borderType":{"desc":"\n\n\n<p>x-axis cells border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"x.itemStyle.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"x.itemStyle.borderCap":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To specify how to draw the end points of the line.\nPossible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;butt&#39;</code>: The ends of lines are squared off at the endpoints.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: The ends of lines are rounded.</li>\n<li><code class=\"codespan\">&#39;square&#39;</code>: The ends of lines are squared off by adding a box with an equal width and half the height of the line&#39;s thickness.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;butt&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineCap\" target=\"_blank\">lineCap</a> for more details.</p>\n","uiControl":{"type":"enum","default":"butt","options":"butt,round,square"}},"x.itemStyle.borderJoin":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To determine the shape used to join two line segments where they meet.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;bevel&#39;</code>: Fills an additional triangular area between the common endpoint of connected segments, and the separate outside rectangular corners of each segment.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: Rounds off the corners of a shape by filling an additional sector of disc centered at the common endpoint of connected segments. The radius for these rounded corners is equal to the line width.</li>\n<li><code class=\"codespan\">&#39;miter&#39;</code>: Connected segments are joined by extending their outside edges to connect at a single point, with the effect of filling an additional lozenge-shaped area. This setting is affected by the \n<code class=\"codespan\">borderMiterLimit</code>\nproperty.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;bevel&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineJoin\" target=\"_blank\">lineJoin</a> for more details.</p>\n","uiControl":{"type":"enum","default":"bevel","options":"bevel,round,miter"}},"x.itemStyle.borderMiterLimit":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the miter limit ratio. Only works when \n<code class=\"codespan\">borderJoin</code>\n is set as <code class=\"codespan\">miter</code>.</p>\n<p>Default value is <code class=\"codespan\">10</code>. Negative、<code class=\"codespan\">0</code>、<code class=\"codespan\">Infinity</code> and <code class=\"codespan\">NaN</code> values are ignored.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/miterLimit\" target=\"_blank\">miterLimit</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"10"}},"x.itemStyle.shadowBlur":{"desc":"\n\n<p>Size of shadow blur. This attribute should be used along with <code class=\"codespan\">shadowColor</code>,<code class=\"codespan\">shadowOffsetX</code>, <code class=\"codespan\">shadowOffsetY</code> to set shadow to component.</p>\n<p>For example:</p>\n<pre><code class=\"lang-ts\">{\n    shadowColor: &#39;rgba(0, 0, 0, 0.5)&#39;,\n    shadowBlur: 10\n}\n</code></pre>\n","uiControl":{"type":"number","default":"","min":"0","step":"0.5"}},"x.itemStyle.shadowColor":{"desc":"\n\n<p>Shadow color. Support same format as <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color","default":""}},"x.itemStyle.shadowOffsetX":{"desc":"\n\n<p>Offset distance on the horizontal direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"x.itemStyle.shadowOffsetY":{"desc":"\n\n<p>Offset distance on the vertical direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"x.itemStyle.opacity":{"desc":"\n\n<p>Opacity of the component. Supports value from 0 to 1, and the component will not be drawn when set to 0.</p>\n","uiControl":{"type":"number","default":"1","min":"0","max":"1","step":"0.01"}},"x.silent":{"desc":"\n\n\n\n<p>Whether to ignore mouse events. Default value is false, for triggering and responding to mouse events.</p>\n","uiControl":{"type":"boolean"}},"x.cursor":{"desc":"<p>Mouse cursor when hovering on the cell.</p>\n"},"x.z2":{"desc":"<p>Specify the z-index (z-order) of the cell.\nUsed when style conflict - especially for thick border style.</p>\n"},"x.levelSize":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p><strong>[[The rule of cell size]]</strong></p>\n<ul>\n<li>option <code class=\"codespan\">levelSize</code><ul>\n<li>It specifies the size of all cells in a row or a column.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell height of a row (&quot;level&quot; refers to a row).</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell width of a column (&quot;level&quot; refers to a column).</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.levelSize</code> specifies the default size of every columns or rows.</li>\n<li><code class=\"codespan\">matrix.levels[i].levelSize</code> specifies the size of a certain column or row.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>option <code class=\"codespan\">size</code><ul>\n<li>It specifies the size of a single cell.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell width.</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell height.</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.x/y.data[i].size</code></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p>The value of <code class=\"codespan\">levelSize</code> or <code class=\"codespan\">size</code> can be:</p>\n<ul>\n<li>Unspecified(default): The width or height is evenly distributed.</li>\n<li><code class=\"codespan\">number</code>: Represents pixel value.</li>\n<li><code class=\"codespan\">string</code>: Percentage value (e.g., <code class=\"codespan\">&#39;33%&#39;</code>), representing the percentage relative to the width (in <code class=\"codespan\">matrix.x</code>) or height (in <code class=\"codespan\">matrix.y</code>) of the matrix.</li>\n</ul>\n<p>For example:</p>\n<pre><code class=\"lang-js\">{\n    matrix: {\n        x: {\n            // The height of the second row is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other row height are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The width of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell width are evenly distributed.\n                // ...\n            ]\n        },\n        y: {\n            // The width of the second column is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other column width are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The height of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell height are evenly distributed.\n                // ...\n            ]\n        },\n        // ...\n    },\n}\n</code></pre>\n"},"x.levels":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Settings for each column(in <code class=\"codespan\">matrix.x</code>) or row(in <code class=\"codespan\">matrix.y</code>). The first element represents the first column/row, and so on.</p>\n<ul>\n<li>If any item in the array is <code class=\"codespan\">null</code>/<code class=\"codespan\">undefined</code>, it means using the default value.</li>\n<li>Otherwise any item in the array should be an object, such as <code class=\"codespan\">{levelSize: number}</code>.</li>\n</ul>\n<p>For example</p>\n<pre><code class=\"lang-js\">matrix: {\n    x: {\n        level: [null, {levelSize: &#39;20%&#39;}]\n        // The second column width should be 20% of\n        // the matrix width.\n        // The first column has no specific setting.\n    },\n    // ...\n},\n</code></pre>\n"},"x.levels.levelSize":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p><strong>[[The rule of cell size]]</strong></p>\n<ul>\n<li>option <code class=\"codespan\">levelSize</code><ul>\n<li>It specifies the size of all cells in a row or a column.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell height of a row (&quot;level&quot; refers to a row).</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell width of a column (&quot;level&quot; refers to a column).</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.levelSize</code> specifies the default size of every columns or rows.</li>\n<li><code class=\"codespan\">matrix.levels[i].levelSize</code> specifies the size of a certain column or row.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>option <code class=\"codespan\">size</code><ul>\n<li>It specifies the size of a single cell.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell width.</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell height.</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.x/y.data[i].size</code></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p>The value of <code class=\"codespan\">levelSize</code> or <code class=\"codespan\">size</code> can be:</p>\n<ul>\n<li>Unspecified(default): The width or height is evenly distributed.</li>\n<li><code class=\"codespan\">number</code>: Represents pixel value.</li>\n<li><code class=\"codespan\">string</code>: Percentage value (e.g., <code class=\"codespan\">&#39;33%&#39;</code>), representing the percentage relative to the width (in <code class=\"codespan\">matrix.x</code>) or height (in <code class=\"codespan\">matrix.y</code>) of the matrix.</li>\n</ul>\n<p>For example:</p>\n<pre><code class=\"lang-js\">{\n    matrix: {\n        x: {\n            // The height of the second row is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other row height are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The width of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell width are evenly distributed.\n                // ...\n            ]\n        },\n        y: {\n            // The width of the second column is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other column width are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The height of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell height are evenly distributed.\n                // ...\n            ]\n        },\n        // ...\n    },\n}\n</code></pre>\n"},"x.dividerLineStyle":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Header divider line style.</p>\n"},"x.dividerLineStyle.color":{"desc":"\n\n<p>header dividerLine color. </p>\n<blockquote>\n<p>Supports setting as solid color using <code class=\"codespan\">rgb(255,255,255)</code>, <code class=\"codespan\">rgba(255,255,255,1)</code>, <code class=\"codespan\">#fff</code>, etc. Also supports setting as gradient color and pattern fill, see <a href=\"#color\">option.color</a> for details</p>\n</blockquote>\n","uiControl":{"type":"color"}},"x.dividerLineStyle.width":{"desc":"\n\n<p>header divider line width.</p>\n","uiControl":{"type":"number","value":"1","min":"0","step":"0.5"}},"x.dividerLineStyle.type":{"desc":"\n\n\n<p>line type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">dashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntype: [5, 10],\n\ndashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"x.dividerLineStyle.dashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">type</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"x.dividerLineStyle.cap":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To specify how to draw the end points of the line.\nPossible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;butt&#39;</code>: The ends of lines are squared off at the endpoints.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: The ends of lines are rounded.</li>\n<li><code class=\"codespan\">&#39;square&#39;</code>: The ends of lines are squared off by adding a box with an equal width and half the height of the line&#39;s thickness.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;butt&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineCap\" target=\"_blank\">lineCap</a> for more details.</p>\n","uiControl":{"type":"enum","default":"butt","options":"butt,round,square"}},"x.dividerLineStyle.join":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To determine the shape used to join two line segments where they meet.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;bevel&#39;</code>: Fills an additional triangular area between the common endpoint of connected segments, and the separate outside rectangular corners of each segment.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: Rounds off the corners of a shape by filling an additional sector of disc centered at the common endpoint of connected segments. The radius for these rounded corners is equal to the line width.</li>\n<li><code class=\"codespan\">&#39;miter&#39;</code>: Connected segments are joined by extending their outside edges to connect at a single point, with the effect of filling an additional lozenge-shaped area. This setting is affected by the \n<code class=\"codespan\">miterLimit</code>\nproperty.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;bevel&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineJoin\" target=\"_blank\">lineJoin</a> for more details.</p>\n","uiControl":{"type":"enum","default":"bevel","options":"bevel,round,miter"}},"x.dividerLineStyle.miterLimit":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the miter limit ratio. Only works when \n<code class=\"codespan\">join</code>\n is set as <code class=\"codespan\">miter</code>.</p>\n<p>Default value is <code class=\"codespan\">10</code>. Negative、<code class=\"codespan\">0</code>、<code class=\"codespan\">Infinity</code> and <code class=\"codespan\">NaN</code> values are ignored.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/miterLimit\" target=\"_blank\">miterLimit</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"10"}},"x.dividerLineStyle.shadowBlur":{"desc":"\n\n<p>Size of shadow blur. This attribute should be used along with <code class=\"codespan\">shadowColor</code>,<code class=\"codespan\">shadowOffsetX</code>, <code class=\"codespan\">shadowOffsetY</code> to set shadow to component.</p>\n<p>For example:</p>\n<pre><code class=\"lang-ts\">{\n    shadowColor: &#39;rgba(0, 0, 0, 0.5)&#39;,\n    shadowBlur: 10\n}\n</code></pre>\n","uiControl":{"type":"number","default":"","min":"0","step":"0.5"}},"x.dividerLineStyle.shadowColor":{"desc":"\n\n<p>Shadow color. Support same format as <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color","default":""}},"x.dividerLineStyle.shadowOffsetX":{"desc":"\n\n<p>Offset distance on the horizontal direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"x.dividerLineStyle.shadowOffsetY":{"desc":"\n\n<p>Offset distance on the vertical direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"x.dividerLineStyle.opacity":{"desc":"\n\n<p>Opacity of the component. Supports value from 0 to 1, and the component will not be drawn when set to 0.</p>\n","uiControl":{"type":"number","default":"1","min":"0","max":"1","step":"0.01"}},"y":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Y-axis header region.</p>\n"},"y.show":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Determines whether to display the header row(in <code class=\"codespan\">matrix.x</code>)/column(in <code class=\"codespan\">matrix.y</code>).</p>\n"},"y.data":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Specifies the data for the y-axis cells. i.e., defined the column/row.</p>\n<pre><code class=\"lang-js\">// Data for a single row\ndata: [&#39;A&#39;, &#39;B&#39;, &#39;C&#39;, &#39;D&#39;, &#39;E&#39;]\n\n// Or if column/row names is not of concern, simply\ndata: Array(5).fill(null) // Five columns or rows\n\n// Data in a tree structure\ndata: [{\n    value: &#39;A&#39;,\n    children: [\n        {\n            value: &#39;A1&#39;,\n            children: [\n                {value: &#39;A1-1&#39;},\n                {value: &#39;A1-2&#39;}\n            ]\n        },\n        {value: &#39;A2&#39;}\n    ]\n}, {\n    value: &#39;B&#39;,\n    children: [\n        {value: &#39;B1&#39;},\n        {value: &#39;B2&#39;}\n    ]\n}]\n</code></pre>\n"},"y.data.value":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>The text in the header cell. Can also be used as a index of this column or row. Optional. If not specified, auto generate a text.</p>\n"},"y.data.children":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>See <a href=\"#matrix.x.data\">matrix.x/y.data</a>.</p>\n"},"y.data.size":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p><strong>[[The rule of cell size]]</strong></p>\n<ul>\n<li>option <code class=\"codespan\">levelSize</code><ul>\n<li>It specifies the size of all cells in a row or a column.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell height of a row (&quot;level&quot; refers to a row).</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell width of a column (&quot;level&quot; refers to a column).</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.levelSize</code> specifies the default size of every columns or rows.</li>\n<li><code class=\"codespan\">matrix.levels[i].levelSize</code> specifies the size of a certain column or row.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>option <code class=\"codespan\">size</code><ul>\n<li>It specifies the size of a single cell.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell width.</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell height.</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.x/y.data[i].size</code></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p>The value of <code class=\"codespan\">levelSize</code> or <code class=\"codespan\">size</code> can be:</p>\n<ul>\n<li>Unspecified(default): The width or height is evenly distributed.</li>\n<li><code class=\"codespan\">number</code>: Represents pixel value.</li>\n<li><code class=\"codespan\">string</code>: Percentage value (e.g., <code class=\"codespan\">&#39;33%&#39;</code>), representing the percentage relative to the width (in <code class=\"codespan\">matrix.x</code>) or height (in <code class=\"codespan\">matrix.y</code>) of the matrix.</li>\n</ul>\n<p>For example:</p>\n<pre><code class=\"lang-js\">{\n    matrix: {\n        x: {\n            // The height of the second row is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other row height are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The width of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell width are evenly distributed.\n                // ...\n            ]\n        },\n        y: {\n            // The width of the second column is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other column width are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The height of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell height are evenly distributed.\n                // ...\n            ]\n        },\n        // ...\n    },\n}\n</code></pre>\n"},"y.label":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Text label of y-axis cells, to explain some data information about graphic item like value, name and so on. <code class=\"codespan\">label</code> is placed under <code class=\"codespan\">itemStyle</code> in ECharts 2.x. In ECharts 3, to make the configuration structure flatter, <code class=\"codespan\">label</code>is taken to be at the same level with <code class=\"codespan\">itemStyle</code>, and has <code class=\"codespan\">emphasis</code> as <code class=\"codespan\">itemStyle</code> does.</p>\n"},"y.label.show":{"desc":"\n\n<p>Whether to show label.</p>\n","uiControl":{"type":"boolean","default":"false"}},"y.label.position":{"desc":"\n\n\n\n<p>Label position.</p>\n<p><strong>Followings are the options: </strong></p>\n<ul>\n<li><p>[x, y]</p>\n<p>  Use relative percentage, or absolute pixel values to represent position of label relative to top-left corner of bounding box.\n  For example:</p>\n<pre><code class=\"lang-ts\">  // Absolute pixel values\n  position: [10, 10],\n  // Relative percentage\n  position: [&#39;50%&#39;, &#39;50%&#39;]\n</code></pre>\n</li>\n<li><p>&#39;top&#39;</p>\n</li>\n<li>&#39;left&#39;</li>\n<li>&#39;right&#39;</li>\n<li>&#39;bottom&#39;</li>\n<li>&#39;inside&#39;</li>\n<li>&#39;insideLeft&#39;</li>\n<li>&#39;insideRight&#39;</li>\n<li>&#39;insideTop&#39;</li>\n<li>&#39;insideBottom&#39;</li>\n<li>&#39;insideTopLeft&#39;</li>\n<li>&#39;insideBottomLeft&#39;</li>\n<li>&#39;insideTopRight&#39;</li>\n<li>&#39;insideBottomRight&#39;</li>\n</ul>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/view.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"enum","options":"top,left,right,bottom,inside,insideLeft,insideRight,insideTop,insideBottom,insideTopLeft,insideBottomLeft,insideTopRight,insideBottomRight,outside"}},"y.label.distance":{"desc":"\n\n<p>Distance to the host graphic element.</p>\n<p>It is valid only when <code class=\"codespan\">position</code> is string value (like <code class=\"codespan\">&#39;top&#39;</code>、<code class=\"codespan\">&#39;insideRight&#39;</code>).</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"number","default":"5","min":"0","step":"0.5"}},"y.label.rotate":{"desc":"\n\n<p>Rotate label, from -90 degree to 90, positive value represents rotate anti-clockwise.</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=bar-label-rotation\" target=\"_blank\">label rotation</a>.</p>\n","uiControl":{"type":"angle","default":"0","min":"-90","max":"90","step":"1"}},"y.label.offset":{"desc":"\n\n<p>Whether to move text slightly. For example: <code class=\"codespan\">[30, 40]</code> means move <code class=\"codespan\">30</code> horizontally and move <code class=\"codespan\">40</code> vertically.</p>\n","uiControl":{"type":"vector","dims":"x,y","step":"0.5","separate":"true"}},"y.label.formatter":{"desc":"<p>Data label formatter, which supports string template and callback function. In either form, <code class=\"codespan\">\\n</code> is supported to represent a new line.</p>\n<p><strong>String template</strong></p>\n<p>Model variation includes:</p>\n<ul>\n<li><code class=\"codespan\">{a}</code>: series name.</li>\n<li><code class=\"codespan\">{b}</code>: the name of a data item.</li>\n<li><code class=\"codespan\">{c}</code>: the value of a data item.</li>\n<li><code class=\"codespan\">{@xxx}</code>: the value of a dimension named <code class=\"codespan\">&#39;xxx&#39;</code>, for example, <code class=\"codespan\">{@product}</code> refers the value of <code class=\"codespan\">&#39;product&#39;</code> dimension.</li>\n<li><code class=\"codespan\">{@[n]}</code>: the value of a dimension at the index of <code class=\"codespan\">n</code>, for example, <code class=\"codespan\">{@[3]}</code> refers the value at dimensions[3].</li>\n</ul>\n<p><strong>example: </strong></p>\n<pre><code class=\"lang-ts\">formatter: &#39;{b}: {@score}&#39;\n</code></pre>\n<p><strong>Callback function</strong></p>\n<p>Callback function is in form of:</p>\n<pre><code class=\"lang-ts\">(params: Object|Array) =&gt; string\n</code></pre>\n<p>where <code class=\"codespan\">params</code> is the single dataset needed by formatter, which is formed as:</p>\n<pre><code class=\"lang-ts\">{\n    componentType: &#39;series&#39;,\n    // Series type\n    seriesType: string,\n    // Series index in option.series\n    seriesIndex: number,\n    // Series name\n    seriesName: string,\n    // Data name, or category name\n    name: string,\n    // Data index in input data array\n    dataIndex: number,\n    // Original data as input\n    data: Object,\n    // Value of data. In most series it is the same as data.\n    // But in some series it is some part of the data (e.g., in map, radar)\n    value: number|Array|Object,\n    // encoding info of coordinate system\n    // Key: coord, like (&#39;x&#39; &#39;y&#39; &#39;radius&#39; &#39;angle&#39;)\n    // value: Must be an array, not null/undefined. Contain dimension indices, like:\n    // {\n    //     x: [2] // values on dimension index 2 are mapped to x axis.\n    //     y: [0] // values on dimension index 0 are mapped to y axis.\n    // }\n    encode: Object,\n    // dimension names list\n    dimensionNames: Array&lt;String&gt;,\n    // data dimension index, for example 0 or 1 or 2 ...\n    // Only work in `radar` series.\n    dimensionIndex: number,\n    // Color of data\n    color: string\n}\n</code></pre>\n<p><strong>How to use <code class=\"codespan\">encode</code> and <code class=\"codespan\">dimensionNames</code>?</strong></p>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    source: [\n        [&#39;Matcha Latte&#39;, 43.3, 85.8, 93.7],\n        [&#39;Milk Tea&#39;, 83.1, 73.4, 55.1],\n        [&#39;Cheese Cocoa&#39;, 86.4, 65.2, 82.5],\n        [&#39;Walnut Brownie&#39;, 72.4, 53.9, 39.1]\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.encode.y[0]]\n</code></pre>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    dimensions: [&#39;product&#39;, &#39;2015&#39;, &#39;2016&#39;, &#39;2017&#39;],\n    source: [\n        {product: &#39;Matcha Latte&#39;, &#39;2015&#39;: 43.3, &#39;2016&#39;: 85.8, &#39;2017&#39;: 93.7},\n        {product: &#39;Milk Tea&#39;, &#39;2015&#39;: 83.1, &#39;2016&#39;: 73.4, &#39;2017&#39;: 55.1},\n        {product: &#39;Cheese Cocoa&#39;, &#39;2015&#39;: 86.4, &#39;2016&#39;: 65.2, &#39;2017&#39;: 82.5},\n        {product: &#39;Walnut Brownie&#39;, &#39;2015&#39;: 72.4, &#39;2016&#39;: 53.9, &#39;2017&#39;: 39.1}\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.dimensionNames[params.encode.y[0]]]\n</code></pre>\n"},"y.label.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#333"}},"y.label.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"y.label.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"y.label.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"y.label.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"y.label.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"y.label.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"y.label.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"y.label.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"y.label.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"y.label.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"y.label.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"y.label.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"y.label.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"y.label.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"y.label.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.width":{"desc":"\n\n<p>Width of text block.</p>\n","uiControl":{"type":"number","default":"100","min":"1","max":"500","step":"1"}},"y.label.height":{"desc":"\n\n<p>Height of text block.</p>\n","uiControl":{"type":"number","default":"50","min":"1","max":"500","step":"1"}},"y.label.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"y.label.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"y.label.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"y.label.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"y.label.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.overflow":{"desc":"\n\n<p>Determine how to display the text when it&#39;s overflow. Available when <code class=\"codespan\">width</code> is set.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the text and trailing with <code class=\"codespan\">ellipsis</code>.</li>\n<li><code class=\"codespan\">&#39;break&#39;</code> Break by word</li>\n<li><code class=\"codespan\">&#39;breakAll&#39;</code> Break by character.</li>\n</ul>\n","uiControl":{"type":"enum","options":"truncate,break,breakAll"}},"y.label.ellipsis":{"desc":"<p>Ellipsis to be displayed when <code class=\"codespan\">overflow</code> is set to <code class=\"codespan\">truncate</code>.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the overflow lines.</li>\n</ul>\n"},"y.label.rich":{"desc":"<p>&quot;Rich text styles&quot; can be defined in this <code class=\"codespan\">rich</code> property. For example:</p>\n<pre><code class=\"lang-ts\">label: {\n    // Styles defined in &#39;rich&#39; can be applied to some fragments\n    // of text by adding some markers to those fragment, like\n    // `{styleName|text content text content}`.\n    // `&#39;\\n&#39;` is the newline character.\n    formatter: [\n        &#39;{a|Style &quot;a&quot; is applied to this snippet}&#39;\n        &#39;{b|Style &quot;b&quot; is applied to this snippet}This snippet use default style{x|use style &quot;x&quot;}&#39;\n    ].join(&#39;\\n&#39;),\n\n    rich: {\n        a: {\n            color: &#39;red&#39;,\n            lineHeight: 10\n        },\n        b: {\n            backgroundColor: {\n                image: &#39;xxx/xxx.jpg&#39;\n            },\n            height: 40\n        },\n        x: {\n            fontSize: 18,\n            fontFamily: &#39;Microsoft YaHei&#39;,\n            borderColor: &#39;#449933&#39;,\n            borderRadius: 4\n        },\n        ...\n    }\n}\n</code></pre>\n<p>For more details, see <a href=\"tutorial.html#Rich%20Text\" target=\"_blank\">Rich Text</a> please.</p>\n"},"y.label.rich.<style_name>.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"null"}},"y.label.rich.<style_name>.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"y.label.rich.<style_name>.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"y.label.rich.<style_name>.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"y.label.rich.<style_name>.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"y.label.rich.<style_name>.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"y.label.rich.<style_name>.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"y.label.rich.<style_name>.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"y.label.rich.<style_name>.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"y.label.rich.<style_name>.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"y.label.rich.<style_name>.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.rich.<style_name>.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"y.label.rich.<style_name>.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"y.label.rich.<style_name>.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"y.label.rich.<style_name>.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"y.label.rich.<style_name>.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"y.label.rich.<style_name>.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.rich.<style_name>.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.rich.<style_name>.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.rich.<style_name>.width":{"desc":"<p>Width of the text block. It is the width of the text by default. In most cases, there is no need to specify it. You may want to use it in some cases like make simple table or using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p><code class=\"codespan\">width</code> can also be percent string, like <code class=\"codespan\">&#39;100%&#39;</code>, which represents the percent of <code class=\"codespan\">contentWidth</code> (that is, the width without <code class=\"codespan\">padding</code>) of its container box. It is based on <code class=\"codespan\">contentWidth</code> because that each text fragment is layout based on the <code class=\"codespan\">content box</code>, where it makes no sense that calculating width based on <code class=\"codespan\">outerWith</code> in prectice.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"y.label.rich.<style_name>.height":{"desc":"<p>Height of the text block. It is the width of the text by default. You may want to use it in some cases like using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"y.label.rich.<style_name>.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"y.label.rich.<style_name>.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.rich.<style_name>.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"y.label.rich.<style_name>.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"y.label.rich.<style_name>.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"y.label.rich.<style_name>.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"y.label.rich.<style_name>.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.rich.<style_name>.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"y.label.richInheritPlainLabel":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Whether rich text inherits plain text style.</p>\n<p>This option is just for backward compatibility.</p>\n<blockquote>\n<p>The <a href=\"#series-scatter.label.rich\">label.rich / textStyle.rich</a> <code class=\"codespan\">fontStyle</code>, <code class=\"codespan\">fontWeight</code>, <code class=\"codespan\">fontSize</code>, <code class=\"codespan\">fontFamily</code>, <code class=\"codespan\">textShadowColor</code>, <code class=\"codespan\">textShadowBlur</code>, <code class=\"codespan\">textShadowOffsetX</code>, <code class=\"codespan\">textShadowOffsetY</code> are changed to inherit the corresponding <a href=\"#series-scatter.label\">plain label styles</a> since echarts v6. You can use <code class=\"codespan\">richInheritPlainLabel: false</code> to restore it. For example,</p>\n<pre><code class=\"lang-js\">option = {\n    richInheritPlainLabel: false, // In most cases, this is enough.\n    xxx1: {\n        // Can also set it here to only control this label.\n        label: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    },\n    xxx2: {\n        textStyle: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    }\n}\n</code></pre>\n</blockquote>\n"},"y.itemStyle":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Graphic style of y-axis cells, <code class=\"codespan\">emphasis</code> is the style when it is highlighted, like being hovered by mouse, or highlighted via legend connect.</p>\n"},"y.itemStyle.color":{"desc":"\n\n<p>y-axis cells color. </p>\n<blockquote>\n<p>Supports setting as solid color using <code class=\"codespan\">rgb(255,255,255)</code>, <code class=\"codespan\">rgba(255,255,255,1)</code>, <code class=\"codespan\">#fff</code>, etc. Also supports setting as gradient color and pattern fill, see <a href=\"#color\">option.color</a> for details</p>\n</blockquote>\n","uiControl":{"type":"color"}},"y.itemStyle.borderColor":{"desc":"\n\n<p>y-axis cells border color, whose format is similar to that of <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color"}},"y.itemStyle.borderWidth":{"desc":"\n\n<p>y-axis cells border width. No border when it is set to be 0.</p>\n<p>y-axis cells border width. No border when it is set to be 0.</p>\n","uiControl":{"type":"number","value":"1","min":"0","step":"0.5"}},"y.itemStyle.borderType":{"desc":"\n\n\n<p>y-axis cells border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"y.itemStyle.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"y.itemStyle.borderCap":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To specify how to draw the end points of the line.\nPossible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;butt&#39;</code>: The ends of lines are squared off at the endpoints.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: The ends of lines are rounded.</li>\n<li><code class=\"codespan\">&#39;square&#39;</code>: The ends of lines are squared off by adding a box with an equal width and half the height of the line&#39;s thickness.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;butt&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineCap\" target=\"_blank\">lineCap</a> for more details.</p>\n","uiControl":{"type":"enum","default":"butt","options":"butt,round,square"}},"y.itemStyle.borderJoin":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To determine the shape used to join two line segments where they meet.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;bevel&#39;</code>: Fills an additional triangular area between the common endpoint of connected segments, and the separate outside rectangular corners of each segment.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: Rounds off the corners of a shape by filling an additional sector of disc centered at the common endpoint of connected segments. The radius for these rounded corners is equal to the line width.</li>\n<li><code class=\"codespan\">&#39;miter&#39;</code>: Connected segments are joined by extending their outside edges to connect at a single point, with the effect of filling an additional lozenge-shaped area. This setting is affected by the \n<code class=\"codespan\">borderMiterLimit</code>\nproperty.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;bevel&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineJoin\" target=\"_blank\">lineJoin</a> for more details.</p>\n","uiControl":{"type":"enum","default":"bevel","options":"bevel,round,miter"}},"y.itemStyle.borderMiterLimit":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the miter limit ratio. Only works when \n<code class=\"codespan\">borderJoin</code>\n is set as <code class=\"codespan\">miter</code>.</p>\n<p>Default value is <code class=\"codespan\">10</code>. Negative、<code class=\"codespan\">0</code>、<code class=\"codespan\">Infinity</code> and <code class=\"codespan\">NaN</code> values are ignored.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/miterLimit\" target=\"_blank\">miterLimit</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"10"}},"y.itemStyle.shadowBlur":{"desc":"\n\n<p>Size of shadow blur. This attribute should be used along with <code class=\"codespan\">shadowColor</code>,<code class=\"codespan\">shadowOffsetX</code>, <code class=\"codespan\">shadowOffsetY</code> to set shadow to component.</p>\n<p>For example:</p>\n<pre><code class=\"lang-ts\">{\n    shadowColor: &#39;rgba(0, 0, 0, 0.5)&#39;,\n    shadowBlur: 10\n}\n</code></pre>\n","uiControl":{"type":"number","default":"","min":"0","step":"0.5"}},"y.itemStyle.shadowColor":{"desc":"\n\n<p>Shadow color. Support same format as <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color","default":""}},"y.itemStyle.shadowOffsetX":{"desc":"\n\n<p>Offset distance on the horizontal direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"y.itemStyle.shadowOffsetY":{"desc":"\n\n<p>Offset distance on the vertical direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"y.itemStyle.opacity":{"desc":"\n\n<p>Opacity of the component. Supports value from 0 to 1, and the component will not be drawn when set to 0.</p>\n","uiControl":{"type":"number","default":"1","min":"0","max":"1","step":"0.01"}},"y.silent":{"desc":"\n\n\n\n<p>Whether to ignore mouse events. Default value is false, for triggering and responding to mouse events.</p>\n","uiControl":{"type":"boolean"}},"y.cursor":{"desc":"<p>Mouse cursor when hovering on the cell.</p>\n"},"y.z2":{"desc":"<p>Specify the z-index (z-order) of the cell.\nUsed when style conflict - especially for thick border style.</p>\n"},"y.levelSize":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p><strong>[[The rule of cell size]]</strong></p>\n<ul>\n<li>option <code class=\"codespan\">levelSize</code><ul>\n<li>It specifies the size of all cells in a row or a column.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell height of a row (&quot;level&quot; refers to a row).</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell width of a column (&quot;level&quot; refers to a column).</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.levelSize</code> specifies the default size of every columns or rows.</li>\n<li><code class=\"codespan\">matrix.levels[i].levelSize</code> specifies the size of a certain column or row.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>option <code class=\"codespan\">size</code><ul>\n<li>It specifies the size of a single cell.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell width.</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell height.</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.x/y.data[i].size</code></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p>The value of <code class=\"codespan\">levelSize</code> or <code class=\"codespan\">size</code> can be:</p>\n<ul>\n<li>Unspecified(default): The width or height is evenly distributed.</li>\n<li><code class=\"codespan\">number</code>: Represents pixel value.</li>\n<li><code class=\"codespan\">string</code>: Percentage value (e.g., <code class=\"codespan\">&#39;33%&#39;</code>), representing the percentage relative to the width (in <code class=\"codespan\">matrix.x</code>) or height (in <code class=\"codespan\">matrix.y</code>) of the matrix.</li>\n</ul>\n<p>For example:</p>\n<pre><code class=\"lang-js\">{\n    matrix: {\n        x: {\n            // The height of the second row is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other row height are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The width of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell width are evenly distributed.\n                // ...\n            ]\n        },\n        y: {\n            // The width of the second column is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other column width are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The height of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell height are evenly distributed.\n                // ...\n            ]\n        },\n        // ...\n    },\n}\n</code></pre>\n"},"y.levels":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Settings for each column(in <code class=\"codespan\">matrix.x</code>) or row(in <code class=\"codespan\">matrix.y</code>). The first element represents the first column/row, and so on.</p>\n<ul>\n<li>If any item in the array is <code class=\"codespan\">null</code>/<code class=\"codespan\">undefined</code>, it means using the default value.</li>\n<li>Otherwise any item in the array should be an object, such as <code class=\"codespan\">{levelSize: number}</code>.</li>\n</ul>\n<p>For example</p>\n<pre><code class=\"lang-js\">matrix: {\n    x: {\n        level: [null, {levelSize: &#39;20%&#39;}]\n        // The second column width should be 20% of\n        // the matrix width.\n        // The first column has no specific setting.\n    },\n    // ...\n},\n</code></pre>\n"},"y.levels.levelSize":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p><strong>[[The rule of cell size]]</strong></p>\n<ul>\n<li>option <code class=\"codespan\">levelSize</code><ul>\n<li>It specifies the size of all cells in a row or a column.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell height of a row (&quot;level&quot; refers to a row).</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell width of a column (&quot;level&quot; refers to a column).</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.levelSize</code> specifies the default size of every columns or rows.</li>\n<li><code class=\"codespan\">matrix.levels[i].levelSize</code> specifies the size of a certain column or row.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>option <code class=\"codespan\">size</code><ul>\n<li>It specifies the size of a single cell.<ul>\n<li>For <code class=\"codespan\">matrix.x</code>, it refers to the cell width.</li>\n<li>For <code class=\"codespan\">matrix.y</code>, it refers to the cell height.</li>\n</ul>\n</li>\n<li>It can be declared in:<ul>\n<li><code class=\"codespan\">matrix.x/y.data[i].size</code></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<p>The value of <code class=\"codespan\">levelSize</code> or <code class=\"codespan\">size</code> can be:</p>\n<ul>\n<li>Unspecified(default): The width or height is evenly distributed.</li>\n<li><code class=\"codespan\">number</code>: Represents pixel value.</li>\n<li><code class=\"codespan\">string</code>: Percentage value (e.g., <code class=\"codespan\">&#39;33%&#39;</code>), representing the percentage relative to the width (in <code class=\"codespan\">matrix.x</code>) or height (in <code class=\"codespan\">matrix.y</code>) of the matrix.</li>\n</ul>\n<p>For example:</p>\n<pre><code class=\"lang-js\">{\n    matrix: {\n        x: {\n            // The height of the second row is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other row height are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The width of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell width are evenly distributed.\n                // ...\n            ]\n        },\n        y: {\n            // The width of the second column is 10% of the matrix width,\n            levels: [undefined, {levelSize: &#39;10%&#39;}]\n            // And the other column width are evenly distributed.\n            levelSize: undefined,\n            data: [\n                {\n                    // The height of the first cell is 30 pixel.\n                    size: 30\n                },\n                // And the other cell height are evenly distributed.\n                // ...\n            ]\n        },\n        // ...\n    },\n}\n</code></pre>\n"},"y.dividerLineStyle":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Header divider line style.</p>\n"},"y.dividerLineStyle.color":{"desc":"\n\n<p>header dividerLine color. </p>\n<blockquote>\n<p>Supports setting as solid color using <code class=\"codespan\">rgb(255,255,255)</code>, <code class=\"codespan\">rgba(255,255,255,1)</code>, <code class=\"codespan\">#fff</code>, etc. Also supports setting as gradient color and pattern fill, see <a href=\"#color\">option.color</a> for details</p>\n</blockquote>\n","uiControl":{"type":"color"}},"y.dividerLineStyle.width":{"desc":"\n\n<p>header divider line width.</p>\n","uiControl":{"type":"number","value":"1","min":"0","step":"0.5"}},"y.dividerLineStyle.type":{"desc":"\n\n\n<p>line type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">dashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntype: [5, 10],\n\ndashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"y.dividerLineStyle.dashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">type</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"y.dividerLineStyle.cap":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To specify how to draw the end points of the line.\nPossible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;butt&#39;</code>: The ends of lines are squared off at the endpoints.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: The ends of lines are rounded.</li>\n<li><code class=\"codespan\">&#39;square&#39;</code>: The ends of lines are squared off by adding a box with an equal width and half the height of the line&#39;s thickness.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;butt&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineCap\" target=\"_blank\">lineCap</a> for more details.</p>\n","uiControl":{"type":"enum","default":"butt","options":"butt,round,square"}},"y.dividerLineStyle.join":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To determine the shape used to join two line segments where they meet.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;bevel&#39;</code>: Fills an additional triangular area between the common endpoint of connected segments, and the separate outside rectangular corners of each segment.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: Rounds off the corners of a shape by filling an additional sector of disc centered at the common endpoint of connected segments. The radius for these rounded corners is equal to the line width.</li>\n<li><code class=\"codespan\">&#39;miter&#39;</code>: Connected segments are joined by extending their outside edges to connect at a single point, with the effect of filling an additional lozenge-shaped area. This setting is affected by the \n<code class=\"codespan\">miterLimit</code>\nproperty.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;bevel&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineJoin\" target=\"_blank\">lineJoin</a> for more details.</p>\n","uiControl":{"type":"enum","default":"bevel","options":"bevel,round,miter"}},"y.dividerLineStyle.miterLimit":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the miter limit ratio. Only works when \n<code class=\"codespan\">join</code>\n is set as <code class=\"codespan\">miter</code>.</p>\n<p>Default value is <code class=\"codespan\">10</code>. Negative、<code class=\"codespan\">0</code>、<code class=\"codespan\">Infinity</code> and <code class=\"codespan\">NaN</code> values are ignored.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/miterLimit\" target=\"_blank\">miterLimit</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"10"}},"y.dividerLineStyle.shadowBlur":{"desc":"\n\n<p>Size of shadow blur. This attribute should be used along with <code class=\"codespan\">shadowColor</code>,<code class=\"codespan\">shadowOffsetX</code>, <code class=\"codespan\">shadowOffsetY</code> to set shadow to component.</p>\n<p>For example:</p>\n<pre><code class=\"lang-ts\">{\n    shadowColor: &#39;rgba(0, 0, 0, 0.5)&#39;,\n    shadowBlur: 10\n}\n</code></pre>\n","uiControl":{"type":"number","default":"","min":"0","step":"0.5"}},"y.dividerLineStyle.shadowColor":{"desc":"\n\n<p>Shadow color. Support same format as <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color","default":""}},"y.dividerLineStyle.shadowOffsetX":{"desc":"\n\n<p>Offset distance on the horizontal direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"y.dividerLineStyle.shadowOffsetY":{"desc":"\n\n<p>Offset distance on the vertical direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"y.dividerLineStyle.opacity":{"desc":"\n\n<p>Opacity of the component. Supports value from 0 to 1, and the component will not be drawn when set to 0.</p>\n","uiControl":{"type":"number","default":"1","min":"0","max":"1","step":"0.01"}},"body":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Body cells, which are the ones except header cells.</p>\n"},"body.data":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Only specify some special cell definitions for Body cells.</p>\n<pre><code class=\"lang-js\">data: [\n    {\n        coord: [[3, 5], [1, 2]], // Required to locate the cell.\n                                 // See the rule below.\n        value: &#39;some_text&#39;,      // Optional. The text to display.\n        mergeCells: true,        // Optional. `false` by default.\n    },\n    {\n        // ...\n    },\n    // ...\n]\n</code></pre>\n<p>Cell locating and reference: see the description in <a href=\"#matrix.body.data.coord\">matrix.body.data</a></p>\n"},"body.data.coord":{"desc":"<p><strong>Body/Corner Cell Locating</strong></p>\n<p>The rule is uniformly applied, such as, in <code class=\"codespan\">matrix.dataToPoint</code> and <code class=\"codespan\">matrix.dataToLayout</code> and <code class=\"codespan\">xxxComponent.coord</code>.</p>\n<p>Suppose the matrix.x/y dimensions (header) are defined as:</p>\n<pre><code class=\"lang-js\">matrix: {\n    x: [{ value: &#39;Xa0&#39;, children: [&#39;Xb0&#39;, &#39;Xb1&#39;] }, &#39;Xa1&#39;],\n    y: [{ value: &#39;Ya0&#39;, children: [&#39;Yb0&#39;, &#39;Yb1&#39;] }],\n}\n</code></pre>\n<pre><code> -----------------------------------------\n |       |       |     Xa0       |       |\n |-------+-------+---------------|  Xa1  |\n |cornerQ|cornerP|  Xb0  |  Xb1  |       |\n |-------+-------+-------+-------+--------\n |       |  Yb0  | bodyR | bodyS |       |\n |  Ya0  |-------+-------+---------------|\n |       |  Yb1  |       |     bodyT     |\n |---------------|------------------------\n</code></pre><ul>\n<li><code class=\"codespan\">Locator number</code>:<ul>\n<li>The term <code class=\"codespan\">locator</code> refers to a integer number to locate cells on x or y direction.</li>\n<li>Use the top-left cell of the body as the origin point <code class=\"codespan\">(0, 0)</code>,<ul>\n<li>the non-negative locator indicates the right/bottom of the origin point;</li>\n<li>the negative locator indicates the left/top of the origin point.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li><code class=\"codespan\">Ordinal number</code> (<code class=\"codespan\">OrdinalNumber</code>):<ul>\n<li>This term follows the same meaning as that in category axis of cartesian. They are non-negative integer, designating each string <code class=\"codespan\">matrix.x.data[i].value</code>/<code class=\"codespan\">matrix.y.data[i].value</code>. <code class=\"codespan\">&#39;Xb0&#39;</code>, <code class=\"codespan\">&#39;Xb2&#39;</code>, <code class=\"codespan\">&#39;Xa1&#39;</code>, <code class=\"codespan\">&#39;Xa0&#39;</code> are assigned with the ordinal numbers <code class=\"codespan\">0</code>, <code class=\"codespan\">1</code>, <code class=\"codespan\">2</code>, <code class=\"codespan\">3</code>. For every leaf dimension cell, <code class=\"codespan\">OrdinalNumber</code> and <code class=\"codespan\">MatrixXYLocator</code> is the same.</li>\n</ul>\n</li>\n<li>A single cell or multiple cells can be determined/located by an array of <code class=\"codespan\">locator number</code> or <code class=\"codespan\">ordinal number</code> or the original <code class=\"codespan\">value</code> string as follows:<ul>\n<li>e.g., the body cell <code class=\"codespan\">bodyS</code> above can be located by:<ul>\n<li><code class=\"codespan\">coord: [1, 0]</code> (Use non-negative integer)</li>\n<li><code class=\"codespan\">coord: [&#39;Xb1&#39;, &#39;Yb0&#39;]</code> (Use the <code class=\"codespan\">value</code> properties in <code class=\"codespan\">matrix.x/y.data</code>)</li>\n<li><code class=\"codespan\">coord: [&#39;Xb1&#39;, 0]</code> (mix them)</li>\n</ul>\n</li>\n<li>e.g., the corner cell <code class=\"codespan\">cornerQ</code> above can be located by:<ul>\n<li><code class=\"codespan\">coord: [-2, -1]</code> (negative <code class=\"codespan\">MatrixXYLocator</code>)</li>\n<li>But it is NOT supported to use <code class=\"codespan\">coord: [&#39;Y1_0&#39;, &#39;X1_0&#39;]</code> (XY transposed form) here.</li>\n</ul>\n</li>\n<li>The dimension (header) cell can be located by negative integers. For example:<ul>\n<li>The center of the node <code class=\"codespan\">&#39;Ya0&#39;</code> can be located by <code class=\"codespan\">[-2, &#39;Ya0&#39;]</code>.</li>\n</ul>\n</li>\n<li>Cross cells: multiple cells can be located. e.g., if using <code class=\"codespan\">[[&#39;Xb0&#39;, &#39;Xb1&#39;], [&#39;Yb0&#39;]]</code>, or using a non-leaf dimension cell to locate, such as <code class=\"codespan\">[&#39;Xa0&#39;, &#39;Yb0&#39;]</code>, it returns only according to the center of the dimension cells, regardless of the body span. (therefore, the result can be on the boundary of two body cells.) And the ordinal number assigned to &#39;Xa0&#39; is 3, thus input <code class=\"codespan\">[3, &#39;Yb0&#39;]</code> get the some result.</li>\n</ul>\n</li>\n<li>In a nutshell, <strong>The formatter of <code class=\"codespan\">matrix.data.coord</code></strong> is as follows:<ul>\n<li><code class=\"codespan\">[2, 8]</code> indicates a cell.</li>\n<li><code class=\"codespan\">[[2, 5], 8]</code> indicates a rect of cells in x range of <code class=\"codespan\">2~5</code> and y <code class=\"codespan\">8</code>.</li>\n<li><code class=\"codespan\">[[2, 5], [7, 8]]</code> indicates a rect of cells in x range of <code class=\"codespan\">2~5</code> and y range of <code class=\"codespan\">7~8</code>.</li>\n<li><code class=\"codespan\">[&#39;aNonLeaf&#39;, 8]</code> indicates a rect of cells in x range of <code class=\"codespan\">aNonLeaf</code> and y <code class=\"codespan\">8</code>.</li>\n<li><code class=\"codespan\">[2, null/undefined/NaN]</code> means y is the entire column (only work on <code class=\"codespan\">coordClamp: true</code>).</li>\n<li><code class=\"codespan\">[null/undefined/NaN, 8]</code> is the opposite (only work on <code class=\"codespan\">coordClamp: true</code>).</li>\n<li><code class=\"codespan\">[[2, 5], null/undefined/NaN]</code> indicates a x range of <code class=\"codespan\">2~5</code> and y is the entire column (only work on <code class=\"codespan\">coordClamp: true</code>)..</li>\n</ul>\n</li>\n<li><p><strong>NOTICE</strong></p>\n<ul>\n<li><code class=\"codespan\">bodyR</code> above is <code class=\"codespan\">[0, 0]</code>**.</li>\n<li>The formatter of <code class=\"codespan\">matrix.data.coord</code> is <code class=\"codespan\">MatrixCoordRangeOption[]</code> as follows.</li>\n</ul>\n</li>\n<li><p>The API <code class=\"codespan\">dataToPoint</code> and <code class=\"codespan\">dataToLayout</code> also uses this locating rule:</p>\n<ul>\n<li>Input <code class=\"codespan\">[&#39;Xa1&#39;, &#39;Yb1&#39;]</code> to <code class=\"codespan\">dataToPoint</code> will get a point in the center of &quot;bodyT&quot;.</li>\n<li>Input <code class=\"codespan\">[&#39;Xa1&#39;, &#39;Yb1&#39;]</code> to <code class=\"codespan\">dataToLayout</code> will get a rect of the &quot;bodyT&quot;.</li>\n</ul>\n</li>\n</ul>\n"},"body.data.coordClamp":{"desc":"<ul>\n<li><code class=\"codespan\">true</code>: <code class=\"codespan\">matrix.body/corner.data[i].coord</code> can use <code class=\"codespan\">[null/undefined/NaN/invalid_values, xxx]</code> or <code class=\"codespan\">[xxx, null/undefined/NaN/invalid_values]</code> to refer to a entire row/column.</li>\n<li><code class=\"codespan\">false</code>: Disallow that. And an error message will be printed in dev mode when such values are used.</li>\n</ul>\n"},"body.data.mergeCells":{"desc":"<p>Body cells or corner cells can be merged.</p>\n"},"body.data.value":{"desc":"<p>Text to display in the cell.</p>\n"},"body.label":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Text label of Body cells, to explain some data information about graphic item like value, name and so on. <code class=\"codespan\">label</code> is placed under <code class=\"codespan\">itemStyle</code> in ECharts 2.x. In ECharts 3, to make the configuration structure flatter, <code class=\"codespan\">label</code>is taken to be at the same level with <code class=\"codespan\">itemStyle</code>, and has <code class=\"codespan\">emphasis</code> as <code class=\"codespan\">itemStyle</code> does.</p>\n"},"body.label.show":{"desc":"\n\n<p>Whether to show label.</p>\n","uiControl":{"type":"boolean","default":"false"}},"body.label.position":{"desc":"\n\n\n\n<p>Label position.</p>\n<p><strong>Followings are the options: </strong></p>\n<ul>\n<li><p>[x, y]</p>\n<p>  Use relative percentage, or absolute pixel values to represent position of label relative to top-left corner of bounding box.\n  For example:</p>\n<pre><code class=\"lang-ts\">  // Absolute pixel values\n  position: [10, 10],\n  // Relative percentage\n  position: [&#39;50%&#39;, &#39;50%&#39;]\n</code></pre>\n</li>\n<li><p>&#39;top&#39;</p>\n</li>\n<li>&#39;left&#39;</li>\n<li>&#39;right&#39;</li>\n<li>&#39;bottom&#39;</li>\n<li>&#39;inside&#39;</li>\n<li>&#39;insideLeft&#39;</li>\n<li>&#39;insideRight&#39;</li>\n<li>&#39;insideTop&#39;</li>\n<li>&#39;insideBottom&#39;</li>\n<li>&#39;insideTopLeft&#39;</li>\n<li>&#39;insideBottomLeft&#39;</li>\n<li>&#39;insideTopRight&#39;</li>\n<li>&#39;insideBottomRight&#39;</li>\n</ul>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/view.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"enum","options":"top,left,right,bottom,inside,insideLeft,insideRight,insideTop,insideBottom,insideTopLeft,insideBottomLeft,insideTopRight,insideBottomRight,outside"}},"body.label.distance":{"desc":"\n\n<p>Distance to the host graphic element.</p>\n<p>It is valid only when <code class=\"codespan\">position</code> is string value (like <code class=\"codespan\">&#39;top&#39;</code>、<code class=\"codespan\">&#39;insideRight&#39;</code>).</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"number","default":"5","min":"0","step":"0.5"}},"body.label.rotate":{"desc":"\n\n<p>Rotate label, from -90 degree to 90, positive value represents rotate anti-clockwise.</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=bar-label-rotation\" target=\"_blank\">label rotation</a>.</p>\n","uiControl":{"type":"angle","default":"0","min":"-90","max":"90","step":"1"}},"body.label.offset":{"desc":"\n\n<p>Whether to move text slightly. For example: <code class=\"codespan\">[30, 40]</code> means move <code class=\"codespan\">30</code> horizontally and move <code class=\"codespan\">40</code> vertically.</p>\n","uiControl":{"type":"vector","dims":"x,y","step":"0.5","separate":"true"}},"body.label.formatter":{"desc":"<p>Data label formatter, which supports string template and callback function. In either form, <code class=\"codespan\">\\n</code> is supported to represent a new line.</p>\n<p><strong>String template</strong></p>\n<p>Model variation includes:</p>\n<ul>\n<li><code class=\"codespan\">{a}</code>: series name.</li>\n<li><code class=\"codespan\">{b}</code>: the name of a data item.</li>\n<li><code class=\"codespan\">{c}</code>: the value of a data item.</li>\n<li><code class=\"codespan\">{@xxx}</code>: the value of a dimension named <code class=\"codespan\">&#39;xxx&#39;</code>, for example, <code class=\"codespan\">{@product}</code> refers the value of <code class=\"codespan\">&#39;product&#39;</code> dimension.</li>\n<li><code class=\"codespan\">{@[n]}</code>: the value of a dimension at the index of <code class=\"codespan\">n</code>, for example, <code class=\"codespan\">{@[3]}</code> refers the value at dimensions[3].</li>\n</ul>\n<p><strong>example: </strong></p>\n<pre><code class=\"lang-ts\">formatter: &#39;{b}: {@score}&#39;\n</code></pre>\n<p><strong>Callback function</strong></p>\n<p>Callback function is in form of:</p>\n<pre><code class=\"lang-ts\">(params: Object|Array) =&gt; string\n</code></pre>\n<p>where <code class=\"codespan\">params</code> is the single dataset needed by formatter, which is formed as:</p>\n<pre><code class=\"lang-ts\">{\n    componentType: &#39;series&#39;,\n    // Series type\n    seriesType: string,\n    // Series index in option.series\n    seriesIndex: number,\n    // Series name\n    seriesName: string,\n    // Data name, or category name\n    name: string,\n    // Data index in input data array\n    dataIndex: number,\n    // Original data as input\n    data: Object,\n    // Value of data. In most series it is the same as data.\n    // But in some series it is some part of the data (e.g., in map, radar)\n    value: number|Array|Object,\n    // encoding info of coordinate system\n    // Key: coord, like (&#39;x&#39; &#39;y&#39; &#39;radius&#39; &#39;angle&#39;)\n    // value: Must be an array, not null/undefined. Contain dimension indices, like:\n    // {\n    //     x: [2] // values on dimension index 2 are mapped to x axis.\n    //     y: [0] // values on dimension index 0 are mapped to y axis.\n    // }\n    encode: Object,\n    // dimension names list\n    dimensionNames: Array&lt;String&gt;,\n    // data dimension index, for example 0 or 1 or 2 ...\n    // Only work in `radar` series.\n    dimensionIndex: number,\n    // Color of data\n    color: string\n}\n</code></pre>\n<p><strong>How to use <code class=\"codespan\">encode</code> and <code class=\"codespan\">dimensionNames</code>?</strong></p>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    source: [\n        [&#39;Matcha Latte&#39;, 43.3, 85.8, 93.7],\n        [&#39;Milk Tea&#39;, 83.1, 73.4, 55.1],\n        [&#39;Cheese Cocoa&#39;, 86.4, 65.2, 82.5],\n        [&#39;Walnut Brownie&#39;, 72.4, 53.9, 39.1]\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.encode.y[0]]\n</code></pre>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    dimensions: [&#39;product&#39;, &#39;2015&#39;, &#39;2016&#39;, &#39;2017&#39;],\n    source: [\n        {product: &#39;Matcha Latte&#39;, &#39;2015&#39;: 43.3, &#39;2016&#39;: 85.8, &#39;2017&#39;: 93.7},\n        {product: &#39;Milk Tea&#39;, &#39;2015&#39;: 83.1, &#39;2016&#39;: 73.4, &#39;2017&#39;: 55.1},\n        {product: &#39;Cheese Cocoa&#39;, &#39;2015&#39;: 86.4, &#39;2016&#39;: 65.2, &#39;2017&#39;: 82.5},\n        {product: &#39;Walnut Brownie&#39;, &#39;2015&#39;: 72.4, &#39;2016&#39;: 53.9, &#39;2017&#39;: 39.1}\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.dimensionNames[params.encode.y[0]]]\n</code></pre>\n"},"body.label.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#333"}},"body.label.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"body.label.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"body.label.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"body.label.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"body.label.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"body.label.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"body.label.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"body.label.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"body.label.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"body.label.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"body.label.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"body.label.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"body.label.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"body.label.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"body.label.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.width":{"desc":"\n\n<p>Width of text block.</p>\n","uiControl":{"type":"number","default":"100","min":"1","max":"500","step":"1"}},"body.label.height":{"desc":"\n\n<p>Height of text block.</p>\n","uiControl":{"type":"number","default":"50","min":"1","max":"500","step":"1"}},"body.label.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"body.label.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"body.label.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"body.label.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"body.label.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.overflow":{"desc":"\n\n<p>Determine how to display the text when it&#39;s overflow. Available when <code class=\"codespan\">width</code> is set.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the text and trailing with <code class=\"codespan\">ellipsis</code>.</li>\n<li><code class=\"codespan\">&#39;break&#39;</code> Break by word</li>\n<li><code class=\"codespan\">&#39;breakAll&#39;</code> Break by character.</li>\n</ul>\n","uiControl":{"type":"enum","options":"truncate,break,breakAll"}},"body.label.ellipsis":{"desc":"<p>Ellipsis to be displayed when <code class=\"codespan\">overflow</code> is set to <code class=\"codespan\">truncate</code>.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the overflow lines.</li>\n</ul>\n"},"body.label.rich":{"desc":"<p>&quot;Rich text styles&quot; can be defined in this <code class=\"codespan\">rich</code> property. For example:</p>\n<pre><code class=\"lang-ts\">label: {\n    // Styles defined in &#39;rich&#39; can be applied to some fragments\n    // of text by adding some markers to those fragment, like\n    // `{styleName|text content text content}`.\n    // `&#39;\\n&#39;` is the newline character.\n    formatter: [\n        &#39;{a|Style &quot;a&quot; is applied to this snippet}&#39;\n        &#39;{b|Style &quot;b&quot; is applied to this snippet}This snippet use default style{x|use style &quot;x&quot;}&#39;\n    ].join(&#39;\\n&#39;),\n\n    rich: {\n        a: {\n            color: &#39;red&#39;,\n            lineHeight: 10\n        },\n        b: {\n            backgroundColor: {\n                image: &#39;xxx/xxx.jpg&#39;\n            },\n            height: 40\n        },\n        x: {\n            fontSize: 18,\n            fontFamily: &#39;Microsoft YaHei&#39;,\n            borderColor: &#39;#449933&#39;,\n            borderRadius: 4\n        },\n        ...\n    }\n}\n</code></pre>\n<p>For more details, see <a href=\"tutorial.html#Rich%20Text\" target=\"_blank\">Rich Text</a> please.</p>\n"},"body.label.rich.<style_name>.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"null"}},"body.label.rich.<style_name>.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"body.label.rich.<style_name>.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"body.label.rich.<style_name>.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"body.label.rich.<style_name>.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"body.label.rich.<style_name>.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"body.label.rich.<style_name>.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"body.label.rich.<style_name>.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"body.label.rich.<style_name>.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"body.label.rich.<style_name>.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"body.label.rich.<style_name>.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.rich.<style_name>.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"body.label.rich.<style_name>.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"body.label.rich.<style_name>.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"body.label.rich.<style_name>.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"body.label.rich.<style_name>.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"body.label.rich.<style_name>.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.rich.<style_name>.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.rich.<style_name>.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.rich.<style_name>.width":{"desc":"<p>Width of the text block. It is the width of the text by default. In most cases, there is no need to specify it. You may want to use it in some cases like make simple table or using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p><code class=\"codespan\">width</code> can also be percent string, like <code class=\"codespan\">&#39;100%&#39;</code>, which represents the percent of <code class=\"codespan\">contentWidth</code> (that is, the width without <code class=\"codespan\">padding</code>) of its container box. It is based on <code class=\"codespan\">contentWidth</code> because that each text fragment is layout based on the <code class=\"codespan\">content box</code>, where it makes no sense that calculating width based on <code class=\"codespan\">outerWith</code> in prectice.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"body.label.rich.<style_name>.height":{"desc":"<p>Height of the text block. It is the width of the text by default. You may want to use it in some cases like using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"body.label.rich.<style_name>.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"body.label.rich.<style_name>.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.rich.<style_name>.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"body.label.rich.<style_name>.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"body.label.rich.<style_name>.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"body.label.rich.<style_name>.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"body.label.rich.<style_name>.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.rich.<style_name>.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"body.label.richInheritPlainLabel":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Whether rich text inherits plain text style.</p>\n<p>This option is just for backward compatibility.</p>\n<blockquote>\n<p>The <a href=\"#series-scatter.label.rich\">label.rich / textStyle.rich</a> <code class=\"codespan\">fontStyle</code>, <code class=\"codespan\">fontWeight</code>, <code class=\"codespan\">fontSize</code>, <code class=\"codespan\">fontFamily</code>, <code class=\"codespan\">textShadowColor</code>, <code class=\"codespan\">textShadowBlur</code>, <code class=\"codespan\">textShadowOffsetX</code>, <code class=\"codespan\">textShadowOffsetY</code> are changed to inherit the corresponding <a href=\"#series-scatter.label\">plain label styles</a> since echarts v6. You can use <code class=\"codespan\">richInheritPlainLabel: false</code> to restore it. For example,</p>\n<pre><code class=\"lang-js\">option = {\n    richInheritPlainLabel: false, // In most cases, this is enough.\n    xxx1: {\n        // Can also set it here to only control this label.\n        label: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    },\n    xxx2: {\n        textStyle: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    }\n}\n</code></pre>\n</blockquote>\n"},"body.itemStyle":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Graphic style of Body cells, <code class=\"codespan\">emphasis</code> is the style when it is highlighted, like being hovered by mouse, or highlighted via legend connect.</p>\n"},"body.itemStyle.color":{"desc":"\n\n<p>Body cells color. </p>\n<blockquote>\n<p>Supports setting as solid color using <code class=\"codespan\">rgb(255,255,255)</code>, <code class=\"codespan\">rgba(255,255,255,1)</code>, <code class=\"codespan\">#fff</code>, etc. Also supports setting as gradient color and pattern fill, see <a href=\"#color\">option.color</a> for details</p>\n</blockquote>\n","uiControl":{"type":"color"}},"body.itemStyle.borderColor":{"desc":"\n\n<p>Body cells border color, whose format is similar to that of <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color"}},"body.itemStyle.borderWidth":{"desc":"\n\n<p>Body cells border width. No border when it is set to be 0.</p>\n<p>Body cells border width. No border when it is set to be 0.</p>\n","uiControl":{"type":"number","value":"1","min":"0","step":"0.5"}},"body.itemStyle.borderType":{"desc":"\n\n\n<p>Body cells border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"body.itemStyle.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"body.itemStyle.borderCap":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To specify how to draw the end points of the line.\nPossible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;butt&#39;</code>: The ends of lines are squared off at the endpoints.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: The ends of lines are rounded.</li>\n<li><code class=\"codespan\">&#39;square&#39;</code>: The ends of lines are squared off by adding a box with an equal width and half the height of the line&#39;s thickness.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;butt&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineCap\" target=\"_blank\">lineCap</a> for more details.</p>\n","uiControl":{"type":"enum","default":"butt","options":"butt,round,square"}},"body.itemStyle.borderJoin":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To determine the shape used to join two line segments where they meet.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;bevel&#39;</code>: Fills an additional triangular area between the common endpoint of connected segments, and the separate outside rectangular corners of each segment.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: Rounds off the corners of a shape by filling an additional sector of disc centered at the common endpoint of connected segments. The radius for these rounded corners is equal to the line width.</li>\n<li><code class=\"codespan\">&#39;miter&#39;</code>: Connected segments are joined by extending their outside edges to connect at a single point, with the effect of filling an additional lozenge-shaped area. This setting is affected by the \n<code class=\"codespan\">borderMiterLimit</code>\nproperty.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;bevel&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineJoin\" target=\"_blank\">lineJoin</a> for more details.</p>\n","uiControl":{"type":"enum","default":"bevel","options":"bevel,round,miter"}},"body.itemStyle.borderMiterLimit":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the miter limit ratio. Only works when \n<code class=\"codespan\">borderJoin</code>\n is set as <code class=\"codespan\">miter</code>.</p>\n<p>Default value is <code class=\"codespan\">10</code>. Negative、<code class=\"codespan\">0</code>、<code class=\"codespan\">Infinity</code> and <code class=\"codespan\">NaN</code> values are ignored.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/miterLimit\" target=\"_blank\">miterLimit</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"10"}},"body.itemStyle.shadowBlur":{"desc":"\n\n<p>Size of shadow blur. This attribute should be used along with <code class=\"codespan\">shadowColor</code>,<code class=\"codespan\">shadowOffsetX</code>, <code class=\"codespan\">shadowOffsetY</code> to set shadow to component.</p>\n<p>For example:</p>\n<pre><code class=\"lang-ts\">{\n    shadowColor: &#39;rgba(0, 0, 0, 0.5)&#39;,\n    shadowBlur: 10\n}\n</code></pre>\n","uiControl":{"type":"number","default":"","min":"0","step":"0.5"}},"body.itemStyle.shadowColor":{"desc":"\n\n<p>Shadow color. Support same format as <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color","default":""}},"body.itemStyle.shadowOffsetX":{"desc":"\n\n<p>Offset distance on the horizontal direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"body.itemStyle.shadowOffsetY":{"desc":"\n\n<p>Offset distance on the vertical direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"body.itemStyle.opacity":{"desc":"\n\n<p>Opacity of the component. Supports value from 0 to 1, and the component will not be drawn when set to 0.</p>\n","uiControl":{"type":"number","default":"1","min":"0","max":"1","step":"0.01"}},"body.silent":{"desc":"\n\n\n\n<p>Whether to ignore mouse events. Default value is false, for triggering and responding to mouse events.</p>\n","uiControl":{"type":"boolean"}},"body.cursor":{"desc":"<p>Mouse cursor when hovering on the cell.</p>\n"},"body.z2":{"desc":"<p>Specify the z-index (z-order) of the cell.\nUsed when style conflict - especially for thick border style.</p>\n"},"corner":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Corner cells, which are the one at the intersection of x and y-axis.</p>\n"},"corner.data":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Only specify some special cell definitions for Corner cells.</p>\n<pre><code class=\"lang-js\">data: [\n    {\n        coord: [[3, 5], [1, 2]], // Required to locate the cell.\n                                 // See the rule below.\n        value: &#39;some_text&#39;,      // Optional. The text to display.\n        mergeCells: true,        // Optional. `false` by default.\n    },\n    {\n        // ...\n    },\n    // ...\n]\n</code></pre>\n<p>Cell locating and reference: see the description in <a href=\"#matrix.body.data.coord\">matrix.body.data</a></p>\n"},"corner.data.coord":{"desc":"<p><strong>Body/Corner Cell Locating</strong></p>\n<p>The rule is uniformly applied, such as, in <code class=\"codespan\">matrix.dataToPoint</code> and <code class=\"codespan\">matrix.dataToLayout</code> and <code class=\"codespan\">xxxComponent.coord</code>.</p>\n<p>Suppose the matrix.x/y dimensions (header) are defined as:</p>\n<pre><code class=\"lang-js\">matrix: {\n    x: [{ value: &#39;Xa0&#39;, children: [&#39;Xb0&#39;, &#39;Xb1&#39;] }, &#39;Xa1&#39;],\n    y: [{ value: &#39;Ya0&#39;, children: [&#39;Yb0&#39;, &#39;Yb1&#39;] }],\n}\n</code></pre>\n<pre><code> -----------------------------------------\n |       |       |     Xa0       |       |\n |-------+-------+---------------|  Xa1  |\n |cornerQ|cornerP|  Xb0  |  Xb1  |       |\n |-------+-------+-------+-------+--------\n |       |  Yb0  | bodyR | bodyS |       |\n |  Ya0  |-------+-------+---------------|\n |       |  Yb1  |       |     bodyT     |\n |---------------|------------------------\n</code></pre><ul>\n<li><code class=\"codespan\">Locator number</code>:<ul>\n<li>The term <code class=\"codespan\">locator</code> refers to a integer number to locate cells on x or y direction.</li>\n<li>Use the top-left cell of the body as the origin point <code class=\"codespan\">(0, 0)</code>,<ul>\n<li>the non-negative locator indicates the right/bottom of the origin point;</li>\n<li>the negative locator indicates the left/top of the origin point.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li><code class=\"codespan\">Ordinal number</code> (<code class=\"codespan\">OrdinalNumber</code>):<ul>\n<li>This term follows the same meaning as that in category axis of cartesian. They are non-negative integer, designating each string <code class=\"codespan\">matrix.x.data[i].value</code>/<code class=\"codespan\">matrix.y.data[i].value</code>. <code class=\"codespan\">&#39;Xb0&#39;</code>, <code class=\"codespan\">&#39;Xb2&#39;</code>, <code class=\"codespan\">&#39;Xa1&#39;</code>, <code class=\"codespan\">&#39;Xa0&#39;</code> are assigned with the ordinal numbers <code class=\"codespan\">0</code>, <code class=\"codespan\">1</code>, <code class=\"codespan\">2</code>, <code class=\"codespan\">3</code>. For every leaf dimension cell, <code class=\"codespan\">OrdinalNumber</code> and <code class=\"codespan\">MatrixXYLocator</code> is the same.</li>\n</ul>\n</li>\n<li>A single cell or multiple cells can be determined/located by an array of <code class=\"codespan\">locator number</code> or <code class=\"codespan\">ordinal number</code> or the original <code class=\"codespan\">value</code> string as follows:<ul>\n<li>e.g., the body cell <code class=\"codespan\">bodyS</code> above can be located by:<ul>\n<li><code class=\"codespan\">coord: [1, 0]</code> (Use non-negative integer)</li>\n<li><code class=\"codespan\">coord: [&#39;Xb1&#39;, &#39;Yb0&#39;]</code> (Use the <code class=\"codespan\">value</code> properties in <code class=\"codespan\">matrix.x/y.data</code>)</li>\n<li><code class=\"codespan\">coord: [&#39;Xb1&#39;, 0]</code> (mix them)</li>\n</ul>\n</li>\n<li>e.g., the corner cell <code class=\"codespan\">cornerQ</code> above can be located by:<ul>\n<li><code class=\"codespan\">coord: [-2, -1]</code> (negative <code class=\"codespan\">MatrixXYLocator</code>)</li>\n<li>But it is NOT supported to use <code class=\"codespan\">coord: [&#39;Y1_0&#39;, &#39;X1_0&#39;]</code> (XY transposed form) here.</li>\n</ul>\n</li>\n<li>The dimension (header) cell can be located by negative integers. For example:<ul>\n<li>The center of the node <code class=\"codespan\">&#39;Ya0&#39;</code> can be located by <code class=\"codespan\">[-2, &#39;Ya0&#39;]</code>.</li>\n</ul>\n</li>\n<li>Cross cells: multiple cells can be located. e.g., if using <code class=\"codespan\">[[&#39;Xb0&#39;, &#39;Xb1&#39;], [&#39;Yb0&#39;]]</code>, or using a non-leaf dimension cell to locate, such as <code class=\"codespan\">[&#39;Xa0&#39;, &#39;Yb0&#39;]</code>, it returns only according to the center of the dimension cells, regardless of the body span. (therefore, the result can be on the boundary of two body cells.) And the ordinal number assigned to &#39;Xa0&#39; is 3, thus input <code class=\"codespan\">[3, &#39;Yb0&#39;]</code> get the some result.</li>\n</ul>\n</li>\n<li>In a nutshell, <strong>The formatter of <code class=\"codespan\">matrix.data.coord</code></strong> is as follows:<ul>\n<li><code class=\"codespan\">[2, 8]</code> indicates a cell.</li>\n<li><code class=\"codespan\">[[2, 5], 8]</code> indicates a rect of cells in x range of <code class=\"codespan\">2~5</code> and y <code class=\"codespan\">8</code>.</li>\n<li><code class=\"codespan\">[[2, 5], [7, 8]]</code> indicates a rect of cells in x range of <code class=\"codespan\">2~5</code> and y range of <code class=\"codespan\">7~8</code>.</li>\n<li><code class=\"codespan\">[&#39;aNonLeaf&#39;, 8]</code> indicates a rect of cells in x range of <code class=\"codespan\">aNonLeaf</code> and y <code class=\"codespan\">8</code>.</li>\n<li><code class=\"codespan\">[2, null/undefined/NaN]</code> means y is the entire column (only work on <code class=\"codespan\">coordClamp: true</code>).</li>\n<li><code class=\"codespan\">[null/undefined/NaN, 8]</code> is the opposite (only work on <code class=\"codespan\">coordClamp: true</code>).</li>\n<li><code class=\"codespan\">[[2, 5], null/undefined/NaN]</code> indicates a x range of <code class=\"codespan\">2~5</code> and y is the entire column (only work on <code class=\"codespan\">coordClamp: true</code>)..</li>\n</ul>\n</li>\n<li><p><strong>NOTICE</strong></p>\n<ul>\n<li><code class=\"codespan\">bodyR</code> above is <code class=\"codespan\">[0, 0]</code>**.</li>\n<li>The formatter of <code class=\"codespan\">matrix.data.coord</code> is <code class=\"codespan\">MatrixCoordRangeOption[]</code> as follows.</li>\n</ul>\n</li>\n<li><p>The API <code class=\"codespan\">dataToPoint</code> and <code class=\"codespan\">dataToLayout</code> also uses this locating rule:</p>\n<ul>\n<li>Input <code class=\"codespan\">[&#39;Xa1&#39;, &#39;Yb1&#39;]</code> to <code class=\"codespan\">dataToPoint</code> will get a point in the center of &quot;bodyT&quot;.</li>\n<li>Input <code class=\"codespan\">[&#39;Xa1&#39;, &#39;Yb1&#39;]</code> to <code class=\"codespan\">dataToLayout</code> will get a rect of the &quot;bodyT&quot;.</li>\n</ul>\n</li>\n</ul>\n"},"corner.data.coordClamp":{"desc":"<ul>\n<li><code class=\"codespan\">true</code>: <code class=\"codespan\">matrix.body/corner.data[i].coord</code> can use <code class=\"codespan\">[null/undefined/NaN/invalid_values, xxx]</code> or <code class=\"codespan\">[xxx, null/undefined/NaN/invalid_values]</code> to refer to a entire row/column.</li>\n<li><code class=\"codespan\">false</code>: Disallow that. And an error message will be printed in dev mode when such values are used.</li>\n</ul>\n"},"corner.data.mergeCells":{"desc":"<p>Body cells or corner cells can be merged.</p>\n"},"corner.data.value":{"desc":"<p>Text to display in the cell.</p>\n"},"corner.label":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Text label of Corner cells, to explain some data information about graphic item like value, name and so on. <code class=\"codespan\">label</code> is placed under <code class=\"codespan\">itemStyle</code> in ECharts 2.x. In ECharts 3, to make the configuration structure flatter, <code class=\"codespan\">label</code>is taken to be at the same level with <code class=\"codespan\">itemStyle</code>, and has <code class=\"codespan\">emphasis</code> as <code class=\"codespan\">itemStyle</code> does.</p>\n"},"corner.label.show":{"desc":"\n\n<p>Whether to show label.</p>\n","uiControl":{"type":"boolean","default":"false"}},"corner.label.position":{"desc":"\n\n\n\n<p>Label position.</p>\n<p><strong>Followings are the options: </strong></p>\n<ul>\n<li><p>[x, y]</p>\n<p>  Use relative percentage, or absolute pixel values to represent position of label relative to top-left corner of bounding box.\n  For example:</p>\n<pre><code class=\"lang-ts\">  // Absolute pixel values\n  position: [10, 10],\n  // Relative percentage\n  position: [&#39;50%&#39;, &#39;50%&#39;]\n</code></pre>\n</li>\n<li><p>&#39;top&#39;</p>\n</li>\n<li>&#39;left&#39;</li>\n<li>&#39;right&#39;</li>\n<li>&#39;bottom&#39;</li>\n<li>&#39;inside&#39;</li>\n<li>&#39;insideLeft&#39;</li>\n<li>&#39;insideRight&#39;</li>\n<li>&#39;insideTop&#39;</li>\n<li>&#39;insideBottom&#39;</li>\n<li>&#39;insideTopLeft&#39;</li>\n<li>&#39;insideBottomLeft&#39;</li>\n<li>&#39;insideTopRight&#39;</li>\n<li>&#39;insideBottomRight&#39;</li>\n</ul>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/view.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"enum","options":"top,left,right,bottom,inside,insideLeft,insideRight,insideTop,insideBottom,insideTopLeft,insideBottomLeft,insideTopRight,insideBottomRight,outside"}},"corner.label.distance":{"desc":"\n\n<p>Distance to the host graphic element.</p>\n<p>It is valid only when <code class=\"codespan\">position</code> is string value (like <code class=\"codespan\">&#39;top&#39;</code>、<code class=\"codespan\">&#39;insideRight&#39;</code>).</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=doc-example/label-position\" target=\"_blank\">label position</a>.</p>\n","uiControl":{"type":"number","default":"5","min":"0","step":"0.5"}},"corner.label.rotate":{"desc":"\n\n<p>Rotate label, from -90 degree to 90, positive value represents rotate anti-clockwise.</p>\n<p>See: <a href=\"https://echarts.apache.org/examples/en/editor.html?c=bar-label-rotation\" target=\"_blank\">label rotation</a>.</p>\n","uiControl":{"type":"angle","default":"0","min":"-90","max":"90","step":"1"}},"corner.label.offset":{"desc":"\n\n<p>Whether to move text slightly. For example: <code class=\"codespan\">[30, 40]</code> means move <code class=\"codespan\">30</code> horizontally and move <code class=\"codespan\">40</code> vertically.</p>\n","uiControl":{"type":"vector","dims":"x,y","step":"0.5","separate":"true"}},"corner.label.formatter":{"desc":"<p>Data label formatter, which supports string template and callback function. In either form, <code class=\"codespan\">\\n</code> is supported to represent a new line.</p>\n<p><strong>String template</strong></p>\n<p>Model variation includes:</p>\n<ul>\n<li><code class=\"codespan\">{a}</code>: series name.</li>\n<li><code class=\"codespan\">{b}</code>: the name of a data item.</li>\n<li><code class=\"codespan\">{c}</code>: the value of a data item.</li>\n<li><code class=\"codespan\">{@xxx}</code>: the value of a dimension named <code class=\"codespan\">&#39;xxx&#39;</code>, for example, <code class=\"codespan\">{@product}</code> refers the value of <code class=\"codespan\">&#39;product&#39;</code> dimension.</li>\n<li><code class=\"codespan\">{@[n]}</code>: the value of a dimension at the index of <code class=\"codespan\">n</code>, for example, <code class=\"codespan\">{@[3]}</code> refers the value at dimensions[3].</li>\n</ul>\n<p><strong>example: </strong></p>\n<pre><code class=\"lang-ts\">formatter: &#39;{b}: {@score}&#39;\n</code></pre>\n<p><strong>Callback function</strong></p>\n<p>Callback function is in form of:</p>\n<pre><code class=\"lang-ts\">(params: Object|Array) =&gt; string\n</code></pre>\n<p>where <code class=\"codespan\">params</code> is the single dataset needed by formatter, which is formed as:</p>\n<pre><code class=\"lang-ts\">{\n    componentType: &#39;series&#39;,\n    // Series type\n    seriesType: string,\n    // Series index in option.series\n    seriesIndex: number,\n    // Series name\n    seriesName: string,\n    // Data name, or category name\n    name: string,\n    // Data index in input data array\n    dataIndex: number,\n    // Original data as input\n    data: Object,\n    // Value of data. In most series it is the same as data.\n    // But in some series it is some part of the data (e.g., in map, radar)\n    value: number|Array|Object,\n    // encoding info of coordinate system\n    // Key: coord, like (&#39;x&#39; &#39;y&#39; &#39;radius&#39; &#39;angle&#39;)\n    // value: Must be an array, not null/undefined. Contain dimension indices, like:\n    // {\n    //     x: [2] // values on dimension index 2 are mapped to x axis.\n    //     y: [0] // values on dimension index 0 are mapped to y axis.\n    // }\n    encode: Object,\n    // dimension names list\n    dimensionNames: Array&lt;String&gt;,\n    // data dimension index, for example 0 or 1 or 2 ...\n    // Only work in `radar` series.\n    dimensionIndex: number,\n    // Color of data\n    color: string\n}\n</code></pre>\n<p><strong>How to use <code class=\"codespan\">encode</code> and <code class=\"codespan\">dimensionNames</code>?</strong></p>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    source: [\n        [&#39;Matcha Latte&#39;, 43.3, 85.8, 93.7],\n        [&#39;Milk Tea&#39;, 83.1, 73.4, 55.1],\n        [&#39;Cheese Cocoa&#39;, 86.4, 65.2, 82.5],\n        [&#39;Walnut Brownie&#39;, 72.4, 53.9, 39.1]\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.encode.y[0]]\n</code></pre>\n<p>When the dataset is like</p>\n<pre><code class=\"lang-ts\">dataset: {\n    dimensions: [&#39;product&#39;, &#39;2015&#39;, &#39;2016&#39;, &#39;2017&#39;],\n    source: [\n        {product: &#39;Matcha Latte&#39;, &#39;2015&#39;: 43.3, &#39;2016&#39;: 85.8, &#39;2017&#39;: 93.7},\n        {product: &#39;Milk Tea&#39;, &#39;2015&#39;: 83.1, &#39;2016&#39;: 73.4, &#39;2017&#39;: 55.1},\n        {product: &#39;Cheese Cocoa&#39;, &#39;2015&#39;: 86.4, &#39;2016&#39;: 65.2, &#39;2017&#39;: 82.5},\n        {product: &#39;Walnut Brownie&#39;, &#39;2015&#39;: 72.4, &#39;2016&#39;: 53.9, &#39;2017&#39;: 39.1}\n    ]\n}\n</code></pre>\n<p>We can get the value of the y-axis via</p>\n<pre><code class=\"lang-ts\">params.value[params.dimensionNames[params.encode.y[0]]]\n</code></pre>\n"},"corner.label.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#333"}},"corner.label.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"corner.label.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"corner.label.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"corner.label.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"corner.label.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"corner.label.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"corner.label.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"corner.label.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"corner.label.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"corner.label.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"corner.label.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"corner.label.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"corner.label.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"corner.label.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"corner.label.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.width":{"desc":"\n\n<p>Width of text block.</p>\n","uiControl":{"type":"number","default":"100","min":"1","max":"500","step":"1"}},"corner.label.height":{"desc":"\n\n<p>Height of text block.</p>\n","uiControl":{"type":"number","default":"50","min":"1","max":"500","step":"1"}},"corner.label.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"corner.label.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"corner.label.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"corner.label.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"corner.label.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.overflow":{"desc":"\n\n<p>Determine how to display the text when it&#39;s overflow. Available when <code class=\"codespan\">width</code> is set.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the text and trailing with <code class=\"codespan\">ellipsis</code>.</li>\n<li><code class=\"codespan\">&#39;break&#39;</code> Break by word</li>\n<li><code class=\"codespan\">&#39;breakAll&#39;</code> Break by character.</li>\n</ul>\n","uiControl":{"type":"enum","options":"truncate,break,breakAll"}},"corner.label.ellipsis":{"desc":"<p>Ellipsis to be displayed when <code class=\"codespan\">overflow</code> is set to <code class=\"codespan\">truncate</code>.</p>\n<ul>\n<li><code class=\"codespan\">&#39;truncate&#39;</code> Truncate the overflow lines.</li>\n</ul>\n"},"corner.label.rich":{"desc":"<p>&quot;Rich text styles&quot; can be defined in this <code class=\"codespan\">rich</code> property. For example:</p>\n<pre><code class=\"lang-ts\">label: {\n    // Styles defined in &#39;rich&#39; can be applied to some fragments\n    // of text by adding some markers to those fragment, like\n    // `{styleName|text content text content}`.\n    // `&#39;\\n&#39;` is the newline character.\n    formatter: [\n        &#39;{a|Style &quot;a&quot; is applied to this snippet}&#39;\n        &#39;{b|Style &quot;b&quot; is applied to this snippet}This snippet use default style{x|use style &quot;x&quot;}&#39;\n    ].join(&#39;\\n&#39;),\n\n    rich: {\n        a: {\n            color: &#39;red&#39;,\n            lineHeight: 10\n        },\n        b: {\n            backgroundColor: {\n                image: &#39;xxx/xxx.jpg&#39;\n            },\n            height: 40\n        },\n        x: {\n            fontSize: 18,\n            fontFamily: &#39;Microsoft YaHei&#39;,\n            borderColor: &#39;#449933&#39;,\n            borderRadius: 4\n        },\n        ...\n    }\n}\n</code></pre>\n<p>For more details, see <a href=\"tutorial.html#Rich%20Text\" target=\"_blank\">Rich Text</a> please.</p>\n"},"corner.label.rich.<style_name>.color":{"desc":"\n\n<p> text color.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"null"}},"corner.label.rich.<style_name>.fontStyle":{"desc":"\n\n<p> font style.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;italic&#39;</code></li>\n<li><code class=\"codespan\">&#39;oblique&#39;</code></li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,italic,oblique"}},"corner.label.rich.<style_name>.fontWeight":{"desc":"\n\n<p> font thick weight.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;normal&#39;</code></li>\n<li><code class=\"codespan\">&#39;bold&#39;</code></li>\n<li><code class=\"codespan\">&#39;bolder&#39;</code></li>\n<li><code class=\"codespan\">&#39;lighter&#39;</code></li>\n<li>100 | 200 | 300 | 400...</li>\n</ul>\n","uiControl":{"type":"enum","default":"normal","options":"normal,bold,bolder,lighter"}},"corner.label.rich.<style_name>.fontFamily":{"desc":"\n\n<p> font family.</p>\n<p>Can also be &#39;serif&#39; , &#39;monospace&#39;, ...</p>\n","uiControl":{"type":"enum","default":"sans-serif","options":"sans-serif,serif,monospace,Arial,Courier New"}},"corner.label.rich.<style_name>.fontSize":{"desc":"\n\n<p> font size.</p>\n","uiControl":{"type":"number","default":"12","min":"1","step":"1"}},"corner.label.rich.<style_name>.align":{"desc":"\n\n<p>Horizontal alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;left&#39;</code></li>\n<li><code class=\"codespan\">&#39;center&#39;</code></li>\n<li><code class=\"codespan\">&#39;right&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">align</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">align</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    align: right,\n    rich: {\n        a: {\n            // `align` is not set, then it will be right\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"left,center,right"}},"corner.label.rich.<style_name>.verticalAlign":{"desc":"\n\n<p>Vertical alignment of text, automatic by default.</p>\n<p>Options are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;top&#39;</code></li>\n<li><code class=\"codespan\">&#39;middle&#39;</code></li>\n<li><code class=\"codespan\">&#39;bottom&#39;</code></li>\n</ul>\n<p>If <code class=\"codespan\">verticalAlign</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">verticalAlign</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    verticalAlign: bottom,\n    rich: {\n        a: {\n            // `verticalAlign` is not set, then it will be bottom\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"enum","options":"top,middle,bottom"}},"corner.label.rich.<style_name>.lineHeight":{"desc":"\n\n<p>Line height of the text fragment.</p>\n<p>If <code class=\"codespan\">lineHeight</code> is not set in <code class=\"codespan\">rich</code>, <code class=\"codespan\">lineHeight</code> in parent level will be used. For example:</p>\n<pre><code class=\"lang-ts\">{\n    lineHeight: 56,\n    rich: {\n        a: {\n            // `lineHeight` is not set, then it will be 56\n        }\n    }\n}\n</code></pre>\n","uiControl":{"type":"number","min":"0","step":"1","default":"12"}},"corner.label.rich.<style_name>.backgroundColor":{"desc":"\n\n<p>Background color of the text fragment.</p>\n<p>Can be color string, like <code class=\"codespan\">&#39;#123234&#39;</code>, <code class=\"codespan\">&#39;red&#39;</code>, <code class=\"codespan\">&#39;rgba(0,23,11,0.3)&#39;</code>.</p>\n<p>Or image can be used, for example:</p>\n<pre><code class=\"lang-ts\">backgroundColor: {\n    image: &#39;xxx/xxx.png&#39;\n    // It can be URL of a image,\n    // or dataURI,\n    // or HTMLImageElement,\n    // or HTMLCanvasElement.\n}\n</code></pre>\n<p><code class=\"codespan\">width</code> or <code class=\"codespan\">height</code> can be specified when using background image, or\nauto adapted by default.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"corner.label.rich.<style_name>.borderColor":{"desc":"\n\n<p>Border color of the text fragment.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color","default":"#fff"}},"corner.label.rich.<style_name>.borderWidth":{"desc":"\n\n<p>Border width of the text fragment.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.rich.<style_name>.borderType":{"desc":"\n\n\n<p>the text fragment border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"corner.label.rich.<style_name>.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"corner.label.rich.<style_name>.borderRadius":{"desc":"\n\n<p>Border radius of the text fragment.</p>\n","uiControl":{"type":"vector","min":"0","dims":"LT,RT, RB, LB"}},"corner.label.rich.<style_name>.padding":{"desc":"\n\n<p>Padding of the text fragment, for example:</p>\n<ul>\n<li><code class=\"codespan\">padding: [3, 4, 5, 6]</code>: represents padding of <code class=\"codespan\">[top, right, bottom, left]</code>.</li>\n<li><code class=\"codespan\">padding: 4</code>: represents <code class=\"codespan\">padding: [4, 4, 4, 4]</code>.</li>\n<li><code class=\"codespan\">padding: [3, 4]</code>: represents <code class=\"codespan\">padding: [3, 4, 3, 4]</code>.</li>\n</ul>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n","uiControl":{"type":"vector","min":"0","dims":"T,R,B,L"}},"corner.label.rich.<style_name>.shadowColor":{"desc":"\n\n<p>Shadow color of the text block.</p>\n","uiControl":{"type":"color"}},"corner.label.rich.<style_name>.shadowBlur":{"desc":"\n\n<p>Show blur of the text block.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.rich.<style_name>.shadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.rich.<style_name>.shadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text block.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.rich.<style_name>.width":{"desc":"<p>Width of the text block. It is the width of the text by default. In most cases, there is no need to specify it. You may want to use it in some cases like make simple table or using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p><code class=\"codespan\">width</code> can also be percent string, like <code class=\"codespan\">&#39;100%&#39;</code>, which represents the percent of <code class=\"codespan\">contentWidth</code> (that is, the width without <code class=\"codespan\">padding</code>) of its container box. It is based on <code class=\"codespan\">contentWidth</code> because that each text fragment is layout based on the <code class=\"codespan\">content box</code>, where it makes no sense that calculating width based on <code class=\"codespan\">outerWith</code> in prectice.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"corner.label.rich.<style_name>.height":{"desc":"<p>Height of the text block. It is the width of the text by default. You may want to use it in some cases like using background image (see <code class=\"codespan\">backgroundColor</code>).</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> specifies the width and height of the content, without <code class=\"codespan\">padding</code>.</p>\n<p>Notice, <code class=\"codespan\">width</code> and <code class=\"codespan\">height</code> only work when <code class=\"codespan\">rich</code> specified.</p>\n"},"corner.label.rich.<style_name>.textBorderColor":{"desc":"\n\n<p>Stroke color of the text.</p>\n<p>If set as <code class=\"codespan\">&#39;inherit&#39;</code>, the color will assigned as visual color, such as series color.</p>\n","uiControl":{"type":"color"}},"corner.label.rich.<style_name>.textBorderWidth":{"desc":"\n\n<p>Stroke line width of the text.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.rich.<style_name>.textBorderType":{"desc":"\n\n\n<p>Stroke line type of the text.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">textBorderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\ntextBorderType: [5, 10],\n\ntextBorderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"corner.label.rich.<style_name>.textBorderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">textBorderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"corner.label.rich.<style_name>.textShadowColor":{"desc":"\n\n<p>Shadow color of the text itself.</p>\n","uiControl":{"type":"color","default":"#000"}},"corner.label.rich.<style_name>.textShadowBlur":{"desc":"\n\n<p>Shadow blue of the text itself.</p>\n","uiControl":{"type":"number","min":"0","step":"0.5"}},"corner.label.rich.<style_name>.textShadowOffsetX":{"desc":"\n\n<p>Shadow X offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.rich.<style_name>.textShadowOffsetY":{"desc":"\n\n<p>Shadow Y offset of the text itself.</p>\n","uiControl":{"type":"number","step":"0.5"}},"corner.label.richInheritPlainLabel":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Whether rich text inherits plain text style.</p>\n<p>This option is just for backward compatibility.</p>\n<blockquote>\n<p>The <a href=\"#series-scatter.label.rich\">label.rich / textStyle.rich</a> <code class=\"codespan\">fontStyle</code>, <code class=\"codespan\">fontWeight</code>, <code class=\"codespan\">fontSize</code>, <code class=\"codespan\">fontFamily</code>, <code class=\"codespan\">textShadowColor</code>, <code class=\"codespan\">textShadowBlur</code>, <code class=\"codespan\">textShadowOffsetX</code>, <code class=\"codespan\">textShadowOffsetY</code> are changed to inherit the corresponding <a href=\"#series-scatter.label\">plain label styles</a> since echarts v6. You can use <code class=\"codespan\">richInheritPlainLabel: false</code> to restore it. For example,</p>\n<pre><code class=\"lang-js\">option = {\n    richInheritPlainLabel: false, // In most cases, this is enough.\n    xxx1: {\n        // Can also set it here to only control this label.\n        label: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    },\n    xxx2: {\n        textStyle: {\n            richInheritPlainLabel: false,\n            rich: {/* ... */},\n        }\n    }\n}\n</code></pre>\n</blockquote>\n"},"corner.itemStyle":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>Graphic style of Corner cells, <code class=\"codespan\">emphasis</code> is the style when it is highlighted, like being hovered by mouse, or highlighted via legend connect.</p>\n"},"corner.itemStyle.color":{"desc":"\n\n<p>Corner cells color. </p>\n<blockquote>\n<p>Supports setting as solid color using <code class=\"codespan\">rgb(255,255,255)</code>, <code class=\"codespan\">rgba(255,255,255,1)</code>, <code class=\"codespan\">#fff</code>, etc. Also supports setting as gradient color and pattern fill, see <a href=\"#color\">option.color</a> for details</p>\n</blockquote>\n","uiControl":{"type":"color"}},"corner.itemStyle.borderColor":{"desc":"\n\n<p>Corner cells border color, whose format is similar to that of <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color"}},"corner.itemStyle.borderWidth":{"desc":"\n\n<p>Corner cells border width. No border when it is set to be 0.</p>\n<p>Corner cells border width. No border when it is set to be 0.</p>\n","uiControl":{"type":"number","value":"1","min":"0","step":"0.5"}},"corner.itemStyle.borderType":{"desc":"\n\n\n<p>Corner cells border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"corner.itemStyle.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"corner.itemStyle.borderCap":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To specify how to draw the end points of the line.\nPossible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;butt&#39;</code>: The ends of lines are squared off at the endpoints.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: The ends of lines are rounded.</li>\n<li><code class=\"codespan\">&#39;square&#39;</code>: The ends of lines are squared off by adding a box with an equal width and half the height of the line&#39;s thickness.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;butt&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineCap\" target=\"_blank\">lineCap</a> for more details.</p>\n","uiControl":{"type":"enum","default":"butt","options":"butt,round,square"}},"corner.itemStyle.borderJoin":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To determine the shape used to join two line segments where they meet.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;bevel&#39;</code>: Fills an additional triangular area between the common endpoint of connected segments, and the separate outside rectangular corners of each segment.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: Rounds off the corners of a shape by filling an additional sector of disc centered at the common endpoint of connected segments. The radius for these rounded corners is equal to the line width.</li>\n<li><code class=\"codespan\">&#39;miter&#39;</code>: Connected segments are joined by extending their outside edges to connect at a single point, with the effect of filling an additional lozenge-shaped area. This setting is affected by the \n<code class=\"codespan\">borderMiterLimit</code>\nproperty.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;bevel&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineJoin\" target=\"_blank\">lineJoin</a> for more details.</p>\n","uiControl":{"type":"enum","default":"bevel","options":"bevel,round,miter"}},"corner.itemStyle.borderMiterLimit":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the miter limit ratio. Only works when \n<code class=\"codespan\">borderJoin</code>\n is set as <code class=\"codespan\">miter</code>.</p>\n<p>Default value is <code class=\"codespan\">10</code>. Negative、<code class=\"codespan\">0</code>、<code class=\"codespan\">Infinity</code> and <code class=\"codespan\">NaN</code> values are ignored.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/miterLimit\" target=\"_blank\">miterLimit</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"10"}},"corner.itemStyle.shadowBlur":{"desc":"\n\n<p>Size of shadow blur. This attribute should be used along with <code class=\"codespan\">shadowColor</code>,<code class=\"codespan\">shadowOffsetX</code>, <code class=\"codespan\">shadowOffsetY</code> to set shadow to component.</p>\n<p>For example:</p>\n<pre><code class=\"lang-ts\">{\n    shadowColor: &#39;rgba(0, 0, 0, 0.5)&#39;,\n    shadowBlur: 10\n}\n</code></pre>\n","uiControl":{"type":"number","default":"","min":"0","step":"0.5"}},"corner.itemStyle.shadowColor":{"desc":"\n\n<p>Shadow color. Support same format as <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color","default":""}},"corner.itemStyle.shadowOffsetX":{"desc":"\n\n<p>Offset distance on the horizontal direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"corner.itemStyle.shadowOffsetY":{"desc":"\n\n<p>Offset distance on the vertical direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"corner.itemStyle.opacity":{"desc":"\n\n<p>Opacity of the component. Supports value from 0 to 1, and the component will not be drawn when set to 0.</p>\n","uiControl":{"type":"number","default":"1","min":"0","max":"1","step":"0.01"}},"corner.silent":{"desc":"\n\n\n\n<p>Whether to ignore mouse events. Default value is false, for triggering and responding to mouse events.</p>\n","uiControl":{"type":"boolean"}},"corner.cursor":{"desc":"<p>Mouse cursor when hovering on the cell.</p>\n"},"corner.z2":{"desc":"<p>Specify the z-index (z-order) of the cell.\nUsed when style conflict - especially for thick border style.</p>\n"},"backgroundStyle":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v6.0.0</code></p>\n</blockquote>\n<p>The style of the entire matrix area.</p>\n"},"backgroundStyle.color":{"desc":"\n\n<p>Entire matrix area  color. </p>\n<blockquote>\n<p>Supports setting as solid color using <code class=\"codespan\">rgb(255,255,255)</code>, <code class=\"codespan\">rgba(255,255,255,1)</code>, <code class=\"codespan\">#fff</code>, etc. Also supports setting as gradient color and pattern fill, see <a href=\"#color\">option.color</a> for details</p>\n</blockquote>\n","uiControl":{"type":"color"}},"backgroundStyle.borderColor":{"desc":"\n\n<p>Entire matrix area  border color, whose format is similar to that of <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color"}},"backgroundStyle.borderWidth":{"desc":"\n\n<p>Entire matrix area  border width. No border when it is set to be 0.</p>\n<p>Entire matrix area  border width. No border when it is set to be 0.</p>\n","uiControl":{"type":"number","value":"1","min":"0","step":"0.5"}},"backgroundStyle.borderType":{"desc":"\n\n\n<p>Entire matrix area  border type.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;solid&#39;</code></li>\n<li><code class=\"codespan\">&#39;dashed&#39;</code></li>\n<li><code class=\"codespan\">&#39;dotted&#39;</code></li>\n</ul>\n<p>Since <code class=\"codespan\">v5.0.0</code>, it can also be a number or a number array to specify the <a href=\"https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray\" target=\"_blank\">dash array</a> of the line. With \n<code class=\"codespan\">borderDashOffset</code>\n, we can make the line style more flexible.</p>\n<p>For example：</p>\n<pre><code class=\"lang-ts\">{\n\nborderType: [5, 10],\n\nborderDashOffset: 5\n}\n</code></pre>\n","uiControl":{"type":"enum","default":"solid","options":"solid,dashed,dotted"}},"backgroundStyle.borderDashOffset":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the line dash offset. With \n<code class=\"codespan\">borderType</code>\n, we can make the line style more flexible.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineDashOffset\" target=\"_blank\">lineDashOffset</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"0"}},"backgroundStyle.borderCap":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To specify how to draw the end points of the line.\nPossible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;butt&#39;</code>: The ends of lines are squared off at the endpoints.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: The ends of lines are rounded.</li>\n<li><code class=\"codespan\">&#39;square&#39;</code>: The ends of lines are squared off by adding a box with an equal width and half the height of the line&#39;s thickness.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;butt&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineCap\" target=\"_blank\">lineCap</a> for more details.</p>\n","uiControl":{"type":"enum","default":"butt","options":"butt,round,square"}},"backgroundStyle.borderJoin":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To determine the shape used to join two line segments where they meet.</p>\n<p>Possible values are:</p>\n<ul>\n<li><code class=\"codespan\">&#39;bevel&#39;</code>: Fills an additional triangular area between the common endpoint of connected segments, and the separate outside rectangular corners of each segment.</li>\n<li><code class=\"codespan\">&#39;round&#39;</code>: Rounds off the corners of a shape by filling an additional sector of disc centered at the common endpoint of connected segments. The radius for these rounded corners is equal to the line width.</li>\n<li><code class=\"codespan\">&#39;miter&#39;</code>: Connected segments are joined by extending their outside edges to connect at a single point, with the effect of filling an additional lozenge-shaped area. This setting is affected by the \n<code class=\"codespan\">borderMiterLimit</code>\nproperty.</li>\n</ul>\n<p>Default value is <code class=\"codespan\">&#39;bevel&#39;</code>. Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/lineJoin\" target=\"_blank\">lineJoin</a> for more details.</p>\n","uiControl":{"type":"enum","default":"bevel","options":"bevel,round,miter"}},"backgroundStyle.borderMiterLimit":{"desc":"<blockquote>\n<p>Since <code class=\"codespan\">v5.0.0</code></p>\n</blockquote>\n\n\n<p>To set the miter limit ratio. Only works when \n<code class=\"codespan\">borderJoin</code>\n is set as <code class=\"codespan\">miter</code>.</p>\n<p>Default value is <code class=\"codespan\">10</code>. Negative、<code class=\"codespan\">0</code>、<code class=\"codespan\">Infinity</code> and <code class=\"codespan\">NaN</code> values are ignored.</p>\n<p>Refer to MDN <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/miterLimit\" target=\"_blank\">miterLimit</a> for more details.</p>\n","uiControl":{"type":"number","min":"0","step":"1","default":"10"}},"backgroundStyle.shadowBlur":{"desc":"\n\n<p>Size of shadow blur. This attribute should be used along with <code class=\"codespan\">shadowColor</code>,<code class=\"codespan\">shadowOffsetX</code>, <code class=\"codespan\">shadowOffsetY</code> to set shadow to component.</p>\n<p>For example:</p>\n<pre><code class=\"lang-ts\">{\n    shadowColor: &#39;rgba(0, 0, 0, 0.5)&#39;,\n    shadowBlur: 10\n}\n</code></pre>\n","uiControl":{"type":"number","default":"","min":"0","step":"0.5"}},"backgroundStyle.shadowColor":{"desc":"\n\n<p>Shadow color. Support same format as <code class=\"codespan\">color</code>.</p>\n","uiControl":{"type":"color","default":""}},"backgroundStyle.shadowOffsetX":{"desc":"\n\n<p>Offset distance on the horizontal direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"backgroundStyle.shadowOffsetY":{"desc":"\n\n<p>Offset distance on the vertical direction of shadow.</p>\n","uiControl":{"type":"number","default":"0","step":"0.5"}},"backgroundStyle.opacity":{"desc":"\n\n<p>Opacity of the component. Supports value from 0 to 1, and the component will not be drawn when set to 0.</p>\n","uiControl":{"type":"number","default":"1","min":"0","max":"1","step":"0.01"}},"borderZ2":{"desc":"<p>The secondary z-index of the outer border and the divider line.</p>\n"},"tooltip":{"desc":"<p>The tooltip for cells, follow the same option as <a href=\"#tooltip\">tooltip</a>. Disabled by default. We can enable tooltip if the text is overflow a cell boundary and truncated.</p>\n<pre><code class=\"lang-ts\">matrix: {\n    tooltip: {\n        show: true\n    },\n    // ...\n}\n</code></pre>\n"}}